    public boolean GetDeviceDigiPin() {
        boolean Status = false;
        char arrdigipinLabels[][] = {
                {'F', 'C', '9', '8'},
                {'J', '3', '2', '7'},
                {'K', '4', '5', '6'},
                {'L', 'M', 'P', 'T'}
        };
        String strPin = "";
        float MinLat = 2.5F, MaxLat = 38.50F, MinLon = 63.50F, MaxLon = 99.50F;
        int row = 0, column = 0, LatDivBy = 4, LonDivBy = 4;
        float LatDivDeg = 0F, LonDivDeg = 0F;
        float lat = Float.parseFloat(strDeviceLatitude);
        float lon = Float.parseFloat(strDeviceLongitude);
        if(lat < MinLat || lat > MaxLat ) {
            System.out.println("Device Latitude Out of Range");
            strDeviceDigiPin = "";
            return false;
        }
        if(lon < MinLon || lon > MaxLon ) {
            System.out.println("Device Longitude Out of Range");
            strDeviceDigiPin = "";
            return false;
        }

        for(int level = 1; level <= 10; level++) {
            LatDivDeg = (MaxLat - MinLat) / LatDivBy;
            LonDivDeg = (MaxLon - MinLon) / LonDivBy;

            float NextLvlMaxLat = MaxLat;
            float NextLvlMinLat = MaxLat - LatDivDeg;
            for(int x=0; x<LatDivBy; x++) {
                if(lat >= NextLvlMinLat && lat < NextLvlMaxLat) {
                    row = x;
                    break;
                } else {
                    NextLvlMaxLat = NextLvlMinLat;
                    NextLvlMinLat = NextLvlMaxLat - LatDivDeg;
                }
            }

            float NextLvlMinLon = MinLon;
            float NextLvlMaxLon = MinLon + LonDivDeg;
            for(int x=0; x<LonDivBy; x++) {
                if(lon >= NextLvlMinLon && lon < NextLvlMaxLon) {
                    column = x;
                    break;
                } else if((NextLvlMinLon + LonDivDeg) < MaxLon) {
                    NextLvlMinLon = NextLvlMaxLon;
                    NextLvlMaxLon = NextLvlMinLon + LonDivDeg;
                } else {
                    column = x;
                }
            }

            if(level == 1) {
                if(arrdigipinLabels[row][column] == '0') {
                    System.out.println("Device DigiPin Out Of Bound");
                    strDeviceDigiPin = "";
                    break;
                }
            }
            strPin = strPin + String.valueOf(arrdigipinLabels[row][column]);

            if(level == 3 || level == 6) {
                strPin = strPin + "-";
            }

            MinLat = NextLvlMinLat; MaxLat = NextLvlMaxLat;
            MinLon = NextLvlMinLon; MaxLon = NextLvlMaxLon;
        }

        strDeviceDigiPin = strPin;

        return Status;
    }
