    Handler SyncByIndexHandler = new Handler() {
        public void handleMessage(Message msg) {
            Bundle messageData = msg.getData();
            String strSyncStatus = messageData.getString("Status");
            switch (msg.what) {
                case -1:
                    TextView tvStatus = (TextView) findViewById(R.id.textViewCurrentProgress);
                    if(tvStatus != null) {
                        tvStatus.setText(strSyncStatus);
                        tvStatus.setTextColor(Color.RED);
                        tvStatus.setTextSize(20);
                    }
                    break;
                case 0:
                    TableLayout tl = (TableLayout) findViewById(R.id.tableLayoutSyncStatus);
                    if (tl != null) {
                        tvStatus = new TextView(getApplicationContext());
                        tvStatus.setText(strSyncStatus);
                        tvStatus.setTextColor(Color.BLACK);
                        tvStatus.setTextSize(20);
                        TableRow tblRow = new TableRow(getApplicationContext());
                        tblRow.addView(tvStatus);
                        tl.addView(tblRow);
                    }
//                    dbUpdateStatus.add(strSyncStatus);
                    if(!strSyncStatus.substring(strSyncStatus.lastIndexOf(":")+2).equalsIgnoreCase("0")) {
                        dbUpdateStatus.add(strSyncStatus);
                    }
                    break;
                case 1:
                    String strUpdateStatus = "";
                    String StrNewFolderName = baseDir + "/csvdb";
                    File folderNewCSVdb = new File(StrNewFolderName);
                    if(folderNewCSVdb.exists()) {
                        if(dbUpdateStatus.size() > 0) {
                            String strMonthlyDataStatus = String.valueOf(OrgID) + "-";
                            strMonthlyDataStatus = strMonthlyDataStatus + String.valueOf(LSO_ID) + "-";
                            strMonthlyDataStatus = strMonthlyDataStatus + String.valueOf(dbUpdateResult) + ".txt";
                            strDbUpdateFile = strMonthlyDataStatus;

                            File updateFile = new File(baseDir + "/config/" + strDbUpdateFile);
                            if(updateFile.exists()) {
                                //Delete earlier status file
                                updateFile.delete();
                            }
                            try {
                                updateFile.createNewFile();
                            } catch (IOException e) {
                                e.printStackTrace();
                            }
                            try {
                                BufferedWriter bwr = new BufferedWriter(new FileWriter(updateFile, true));
                                for(int i=0; i<dbUpdateStatus.size(); i++) {
                                    bwr.write("\r\n");
                                    bwr.write(dbUpdateStatus.get(i));
                                    strUpdateStatus = strUpdateStatus + "\r\n";
                                    strUpdateStatus = strUpdateStatus + dbUpdateStatus.get(i);
                                }
                                bwr.flush();
                                bwr.close();

                                dbUpdateStatus.clear();
                                sendDbUpdateFile = true;
                            } catch (IOException e) {
                                e.printStackTrace();
                            }
                        }
                        String StrOldFolderName = baseDir + "/csvdb_old";
                        File folderOldCSVdb = new File(StrOldFolderName);
                        if(folderOldCSVdb.exists()) {
                            String[] strList = folderOldCSVdb.list();
                            int iCount = strList.length;
                            for (int i = 0; i < iCount; i++) {
                                File oldFile = new File(StrOldFolderName + "/" + strList[i]);
                                if(oldFile.exists()) {
                                    oldFile.delete();
                                }
                            }
                            folderOldCSVdb.delete();
                        }

                        String[] strList = folderNewCSVdb.list();
                        int iCount = strList.length;
                        for (int i = 0; i < iCount; i++) {
                            File newFile = new File(StrNewFolderName + "/" + strList[i]);
                            if(newFile.exists()) {
                                newFile.delete();
                            }
                        }
                        folderNewCSVdb.delete();
                    }

                    ProgressBar pbSync = (ProgressBar) findViewById(R.id.progressBarSync);
                    if (pbSync != null) {
                        pbSync.setVisibility(View.INVISIBLE);
                    }

                    if(!strUpdateStatus.isEmpty()) {
                        strUpdateStatus = "Server Data Sync-up Status:" + strUpdateStatus;
                        CreateAlertDialog(true, false);
                        dlgState = ufin_DIALOG_STATE_SERVER_DB_SYNC_UP_STATUS;
                        dlgAlert.setMessage(strUpdateStatus);
                        AlertDialog dialog = dlgAlert.create();
                        dialog.show();
                        TextView textView = (TextView) dialog.findViewById(android.R.id.message);
                        textView.setTextSize(24);
                        textView.setTextColor(Color.RED);
                    }
//                    Toast toast = Toast.makeText(getBaseContext(), strSyncStatus, Toast.LENGTH_SHORT);
//                    ViewGroup group = (ViewGroup) toast.getView();
//                    if(group != null) {
//                        TextView messageTextView = (TextView) group.getChildAt(0);
//                        messageTextView.setTextSize(28);
//                        toast.show();
//                    }
                    ShowToastMessage(strSyncStatus);
                    InitLogin();
                    strCurrentScreen = getString(R.string.app_name) +
                            ": V" + getString(R.string.app_version) +
                            ", Database: V" + String.valueOf(ufinDbHelper.DATABASE_VERSION);
                    setAppActionbar();
                    break;
                case 2:
                    setAppActionbar();
                    break;
                case 3:
                    if(CurrentContentView == R.layout.activity_sync) {
                        InitServerSync();
                    } else if(CurrentContentView == R.layout.activity_desktop) {
                        InitMsgBox();
                    } else if(CurrentContentView == R.layout.activity_login) {
                        TextView tv = (TextView) findViewById(R.id.textViewStartOfDaySyncupTimestamp);
//                        tv.setText(strStartOfDaySyncupTimestamp);
                        String strSODSyncupTimestamp = "";
                        SimpleDateFormat sdf1 = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.ENGLISH);
//                        SimpleDateFormat sdf2 = new SimpleDateFormat("dd-MMM-yyyy HH:mm:ss", Locale.ENGLISH);
                        SimpleDateFormat sdf2 = new SimpleDateFormat("dd-MMM-yyyy hh:mm:ss a", Locale.ENGLISH);
                        Date strSOD = null;
                        try {
                            strSOD = sdf1.parse(strStartOfDaySyncupTimestamp);
                            strSODSyncupTimestamp = sdf2.format(strSOD);
                        } catch (ParseException e) {
//                throw new RuntimeException(e);
                        }
                        tv.setText(strSODSyncupTimestamp);
                    }
                    break;
                case 5:
                    SQLiteBusy = true;
                    CreateAlertDialog(true, true);
                    dlgState = ufin_DIALOG_STATE_SERVER_DB_SYNC_UP;
                    dlgAlert.setMessage(MSG_ufin_SERVER_DB_SYNC_UP);
                    AlertDialog dialog = dlgAlert.create();
                    dialog.show();
                    TextView textView = (TextView) dialog.findViewById(android.R.id.message);
                    textView.setTextSize(30);
                    textView.setTextColor(Color.RED);
                    break;
            }
        }
    };

