    public void CheckWIPDisbursementDate() {
        arrlistWIP.clear();

        SQLite_getRevisitMemberList();

        for(int i=0; i<RevisitMemberList.size(); i++) {
//bmp 18-Jan-23
            //Exclude from WIP - Punarbhet Member entry with Expired Disbursement Date
            try {
                String strTargetLoanDisbursementDate = RevisitMemberList.get(i).TargetLoanDisbursementDate;
                if(strTargetLoanDisbursementDate.length() >= 10) {
                    SimpleDateFormat sdf = new SimpleDateFormat("dd-MMM-yyyy", Locale.ENGLISH);
                    Date date = sdf.parse(strTargetLoanDisbursementDate);
//bmp 08-Jun-23
//                    Calendar calTargetLoanDisbursementDate = Calendar.getInstance();
//                    calTargetLoanDisbursementDate.set(Calendar.YEAR, date.getYear());
//                    calTargetLoanDisbursementDate.set(Calendar.MONTH, date.getMonth());
//                    calTargetLoanDisbursementDate.set(Calendar.DATE, date.getDate());
//                    long lTargetLoanDisbursementDate = calTargetLoanDisbursementDate.getTimeInMillis();
                    long lTargetLoanDisbursementDate = date.getTime();
//bmp 08-Jun-23
                    Calendar calToday = Calendar.getInstance();
                    long lToday = calToday.getTimeInMillis();
                    long lOneMonth = (1000L * 60L * 60L * 24L * 30L);
                    long lLimitday = lTargetLoanDisbursementDate + lOneMonth;
                    if(lToday >= lLimitday) {
                        continue;
                    }
                }
            } catch (Exception e) {
                System.out.println(e.getMessage());
            }
//bmp 18-Jan-23
            if (RevisitMemberList.get(i).RevisitMemberStatus >= clsRevisitMember.REVISIT_MEMBER_STATUS_READYGROUP) {
                boolean newFlag = true;
                for (int j = 0; j < arrlistWIP.size(); j++) {
                    if (RevisitMemberList.get(i).GroupID == arrlistWIP.get(j).GroupID) {
                        newFlag = false;
                        break;
                    }
                }
                if (newFlag) {
//bmp 02-Sep-24
//                    boolean grtokFlag = false;
//                    for (int j = 0; j < SyncGroupStatusUpdate.size(); j++) {
//                        if(SyncGroupStatusUpdate.get(j).GroupID == RevisitMemberList.get(i).GroupID) {
//                            if(SyncGroupStatusUpdate.get(j).Status == clsNewGroup.GROUP_STATUS_GRT_OK) {
//                                grtokFlag = true;
//                                break;
//                            }
//                        }
//                    }
//                    if(grtokFlag)
//                        continue;
//bmp 02-Sep-24

                    ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                    // Gets the data repository in write mode
                    SQLiteDatabase db = mDbHelper.getReadableDatabase();

                    // Define a projection that specifies which columns from the database
                    // you will actually use after this query.
                    String[] projection1 = {
                            ufinDbContract.MemberData.COLUMN_NAME_MemberID,
                            ufinDbContract.MemberData.COLUMN_NAME_GroupID,
                            ufinDbContract.MemberData.COLUMN_NAME_AddressID,
                            ufinDbContract.MemberData.COLUMN_NAME_MemberFamilyDetailsID,
                    };
                    String selection1 = ufinDbContract.MemberData.COLUMN_NAME_GroupID + "=" + "'" + String.valueOf(RevisitMemberList.get(i).GroupID) + "'";
                    Cursor c1 = db.query(
                            ufinDbContract.MemberData.TABLE_NAME,  // The table to query
                            projection1,                               // The columns to return
                            selection1,                                // The columns for the WHERE clause
                            null,
                            null,                                     // don't group the rows
                            null,                                     // don't filter by row groups
                            null                                     // The sort order
                    );

                    try {
                        if (c1 != null && c1.moveToFirst()) {
                            if (c1.getCount() > 0) {
                                for(int j=0; j<c1.getCount(); j++) {
                                    clsWIP newWIP = new clsWIP();
                                    try {
                                        newWIP.GroupID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_GroupID)));
                                    } catch (NumberFormatException e) {
                                        newWIP.GroupID = 0;
                                    }
                                    try {
                                        newWIP.MemberID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_MemberID)));
                                    } catch (NumberFormatException e) {
                                        newWIP.MemberID = 0;
                                    }
                                    try {
                                        newWIP.AddressID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_AddressID)));
                                    } catch (NumberFormatException e) {
                                        newWIP.AddressID = 0;
                                    }
                                    try {
                                        newWIP.MemberFamilyDetailsID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_MemberFamilyDetailsID)));
                                    } catch (NumberFormatException e) {
                                        newWIP.MemberFamilyDetailsID = 0;
                                    }
                                    arrlistWIP.add(newWIP);
                                    c1.moveToNext();
                                }
                            }
                        }
                    } finally {
                        if(c1 != null) { c1.close(); }
                        db.close();
                    }
                }
            }
        }

        arrlistWIPGroupID.clear();
        for(int j=0; j<arrlistWIP.size(); j++) {
            boolean flagNew = true;
            for(int k=0; k<arrlistWIPGroupID.size(); k++) {
                if(arrlistWIP.get(j).GroupID == arrlistWIPGroupID.get(k)) {
                    flagNew = false;
                    break;
                }
            }
            if(flagNew) {
                arrlistWIPGroupID.add(arrlistWIP.get(j).GroupID);
            }
        }
    }
