        tv = (TextView) findViewById(R.id.textViewUploadStatus);
        tv.setText(strUploadStatus);

        if (pbSync != null) {
            pbSync.setIndeterminate(true);
            pbSync.setVisibility(View.INVISIBLE);
        }

        if(selectedCollectionCenterID > 0) {
//            Calendar cal = Calendar.getInstance();
            long lToday = cal.getTimeInMillis();
            boolean flagRevisitDue = false;
            for(int i=0; i<RevisitMemberList.size(); i++) {
                if(RevisitMemberList.get(i).CenterID != selectedCollectionCenterID)
                    continue;
                if(     (!RevisitMemberList.get(i).ListType.equalsIgnoreCase("Yellow-I")) &&
                        (!RevisitMemberList.get(i).ListType.equalsIgnoreCase("Yellow-II")) )
                    continue;
                String strMaturityDate = RevisitMemberList.get(i).MaturityDate;
                strMaturityDate = strMaturityDate.substring(0, 10);
                String[] strSplit = strMaturityDate.split("-");
                int iMaturityYear = Integer.parseInt(strSplit[0]);
                int iMaturityMonth = Integer.parseInt(strSplit[1]);
                if(iMaturityYear > iMDLimitYear)
                    continue;
                if( (iMaturityYear == iMDLimitYear) && (iMaturityMonth > iMDLimitMonth) )
                    continue;
                if(RevisitMemberList.get(i).LongMaturityDate < lToday)
                    continue;
                flagRevisitDue = true;
                break;
            }
            if(flagRevisitDue) {
                bt = (Button) findViewById(R.id.buttonRevisit);
                bt.performClick();
            } else {
                selectedCollectionCenterID = 0;
            }
        }
