                if(AdditionalDetails.LoanGuarantorID ==
                        Member.get(i).MemberID) {
                    indexGuarantor = i;
                    GuarantorIsFamilyMember = true;
                    if(Member.get(i).RelationID != RelationIDSpouse)
                        GuarantorIsFamilyMemberOtherThanSpouse = true;
                    break;
                }
