    public void CheckForMissingCollectionPackets() {
        Calendar cal = Calendar.getInstance();
        Date date = cal.getTime();
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd", Locale.ENGLISH);
        String strToday = sdf.format(date);
        String strSearch = "CollectionDate=" + strToday;

        ArrayList<String> strPackets = new ArrayList<String>();
        ArrayList<String> strLog = new ArrayList<String>();
        ArrayList<String> strNotUploaded = new ArrayList<String>();
        strPackets.clear();
        strLog.clear();
        strNotUploaded.clear();

        try {
            //Read today's generated packets
            File packetFile = new File(baseDir + "/config/" + strPacketFile);
            BufferedReader br = new BufferedReader(new FileReader(packetFile));
            String strLine;
            while ((strLine = br.readLine()) != null) {
                if(strLine.contains(strSearch)) {
                    strPackets.add(strLine);
                }
            }
            br.close();
            //Read today's uploaded packets
            File logFile = new File(baseDir + "/config/" + strLogFile);
            br = new BufferedReader(new FileReader(logFile));
            while ((strLine = br.readLine()) != null) {
                if(strLine.contains(strSearch)) {
                    strLog.add(strLine);
                }
            }
            br.close();
            //Copy today's Not Uploaded packets
            for(int i=0; i<strPackets.size(); i++) {
                boolean flagNotUploaded = true;
                for(int j=0; j<strLog.size(); j++) {
                    if(strLog.get(j).contains(strPackets.get(i))) {
                        flagNotUploaded = false;
                        break;
                    }
                }
                if(flagNotUploaded) {
                    strNotUploaded.add(strPackets.get(i));
                }
            }

            for(int i=0; i<strNotUploaded.size(); i++) {
                String strPacket = strNotUploaded.get(i);
                String[] strSplit = strPacket.split("&");
                String strTimeStamp = "";
                long lrecordID = 0;
                String strPacketType = "";
                //Get SyncID, recordID, PacketType of today's Not Uploaded packets
                for(int j=0; j<strSplit.length; j++) {
                    String[] strSplit2 = strSplit[j].split("=");
//                    if(strSplit2[0].startsWith("MemberID")) {
                    if(strSplit2[0].startsWith("MemberID") || strSplit2[0].startsWith("?MemberID")) {
                        lrecordID = Long.parseLong(strSplit2[1]);
                    } else if(strSplit2[0].startsWith("CollectionDate")) {
                        strTimeStamp = strSplit2[1];
                    } else if(strSplit2[0].startsWith("SMSResponse")) {
                        strPacketType = "CollectionSMS";
                    } else if(strSplit2[0].startsWith("ModuleID")) {
                        if(strSplit2[1].equalsIgnoreCase("3")) {
                            strPacketType = "RDReceipt";
                        } else {
                            strPacketType = "CollectionDetails";
                        }
                    } else if(strSplit2[0].startsWith("Nar_500")) {
                        strPacketType = "CollectionNarration";
                        SimpleDateFormat sdf3 = new SimpleDateFormat("ddHHmmssSSS", Locale.ENGLISH);
                        String Str1 = sdf3.format(date) + String.format("%08d", LSO_ID);
                        Str1 = Str1.replaceFirst("^0+(?!$)", "");
                        try {
                            lrecordID = Long.parseLong(Str1);
                        } catch (NumberFormatException e) {
                            e.printStackTrace();
                        }
                    }
                    if((lrecordID > 0) && (!strTimeStamp.isEmpty()) && (!strPacketType.isEmpty()))
                        break;
                }
                clsRecordsToSync newRec = new MainActivity.clsRecordsToSync();
                newRec.SyncID = strTimeStamp;
                newRec.recordID = lrecordID;
                newRec.recordInserted = true;
                newRec.recordReady = true;
                newRec.PostParams = strPacket;
                if(strPacketType.equalsIgnoreCase("CollectionDetails")) {
                    SyncUpdateCollectionDetails.add(newRec);
                } else if(strPacketType.equalsIgnoreCase("RDReceipt")) {
                    SyncUpdateRDReceipt.add(newRec);
                } else if(strPacketType.equalsIgnoreCase("CollectionSMS")) {
                    SyncCollectionSMS.add(newRec);
                } else if(strPacketType.equalsIgnoreCase("CollectionNarration")) {
                    SyncUpdateCollectionNarration.add(newRec);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
    public void importDB() {
        String DATABASE_NAME = "ufin.db";
        try {
            // Open the empty db as the output stream
            File dbFile = new File(this.getDatabasePath(DATABASE_NAME).getAbsolutePath());
            FileOutputStream fos = new FileOutputStream(dbFile);

            String inFileName = baseDir + "/config/" + DATABASE_NAME;
            InputStream input = new FileInputStream(inFileName);

            // Transfer bytes from the inputfile to the outputfile
            byte[] buffer = new byte[1024];
            int length;
            while ((length = input.read(buffer)) > 0) {
                fos.write(buffer, 0, length);
            }
            // Close the streams
            fos.flush();
            fos.close();
            input.close();
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
    }
    public void exportDB() {
        String DATABASE_NAME = "ufin.db";
        try {
            File dbFile = new File(this.getDatabasePath(DATABASE_NAME).getAbsolutePath());
            FileInputStream fis = new FileInputStream(dbFile);

            String outFileName = baseDir + "/config/" + DATABASE_NAME;

            // Open the empty db as the output stream
            OutputStream output = new FileOutputStream(outFileName);

            // Transfer bytes from the inputfile to the outputfile
            byte[] buffer = new byte[1024];
            int length;
            while ((length = fis.read(buffer)) > 0) {
                output.write(buffer, 0, length);
            }
            // Close the streams
            output.flush();
            output.close();
            fis.close();
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
    }
