    public void OnClickPIF(View v) {
        CustomViewPager viewPager = (CustomViewPager) findViewById(R.id.viewpagerPIF);
        if(viewPager != null)
            viewPager.requestFocus();

        switch(v.getId()) {
            case R.id.buttonPrevious:
                iCurrentScreen--;
                if(iCurrentScreen < PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER)
                    iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER;
                viewPager.setCurrentItem(iCurrentScreen);
                Spinner sp = (Spinner) findViewById(R.id.spinnerPIFMember);
                if(iCurrentScreen == PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER)
                    sp.setEnabled(true);
                else
                    sp.setEnabled(false);
                break;
            case R.id.buttonNext:
                if(ValidatePIFscreen()) {
                    viewPager = (CustomViewPager) findViewById(R.id.viewpagerPIF);
                    iCurrentScreen++;
                    if(iCurrentScreen == PIF_FRAGMENT_SEQUENCE_NUMBER_ROLL_OVER)
                        iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER;
                    viewPager.setCurrentItem(iCurrentScreen);
                }
                sp = (Spinner) findViewById(R.id.spinnerPIFMember);
                if(iCurrentScreen == PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER)
                    sp.setEnabled(true);
                else
                    sp.setEnabled(false);
                break;
            case R.id.buttonFirst:
                viewPager = (CustomViewPager) findViewById(R.id.viewpagerPIF);
                iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_FAMILY;
                viewPager.setCurrentItem(iCurrentScreen);
                iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER;
                viewPager.setCurrentItem(iCurrentScreen);
                sp = (Spinner) findViewById(R.id.spinnerPIFMember);
                sp.setEnabled(true);
                break;
            case R.id.buttonLast:
                viewPager = (CustomViewPager) findViewById(R.id.viewpagerPIF);
                iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_DOCUMENTS;
                viewPager.setCurrentItem(iCurrentScreen);
                iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_SUBMIT;
                viewPager.setCurrentItem(iCurrentScreen);
                sp = (Spinner) findViewById(R.id.spinnerPIFMember);
                sp.setEnabled(false);
                break;
            case R.id.buttonClosePIF:
                CreateAlertDialog(true, true);
                dlgState = ufin_DIALOG_STATE_CLOSE;
                dlgAlert.setMessage(MSG_ufin_CONFIRM_CLOSE);
                AlertDialog dialog = dlgAlert.create();
                dialog.show();
                TextView textView = (TextView) dialog.findViewById(android.R.id.message);
                textView.setTextSize(30);
                textView.setTextColor(Color.RED);
                break;
            case R.id.buttonSavePIF:
                if(progressBarWait == true)
                    break;
                if(Member.size() <= 0) {
                    InitDesktop();
                    break;
                } else {
                    if( Member.get(0).Fname.isEmpty() || (Member.get(0).Mname.isEmpty() && Member.get(0).Lname.isEmpty()) ) {
                        InitDesktop();
                        break;
                    }
                }

                AsyncCallWS_SaveMemberPIF taskSaveMemberPIF = new AsyncCallWS_SaveMemberPIF();
                taskSaveMemberPIF.execute();

                break;
        }
    }

