    private class AsyncCallWS_Logout extends AsyncTask<String, Void, Void> {
        @Override
        protected void onPreExecute() {
            ProgressBar pbSync = (ProgressBar) findViewById(R.id.progressBarSync);
            if (pbSync != null) {
                pbSync.setIndeterminate(true);
                pbSync.setVisibility(View.VISIBLE);
            }
            Button bt1 = (Button) findViewById(R.id.buttonSyncClose);
            bt1.setEnabled(false);
            Button bt = (Button) findViewById(R.id.buttonLogout);
            bt.setEnabled(false);
        }
        @Override
        protected void onProgressUpdate(Void... values) {
        }
        @Override
        protected Void doInBackground(String... strings) {
            //Wait till background Server-Sync thread is busy
            while (SQLiteBusy) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
            //Server-Sync background thread will Wait
            SQLiteBusy = true;

            return null;
        }
        @Override
        protected void onPostExecute(Void result) {
            ProgressBar pbSync = (ProgressBar) findViewById(R.id.progressBarSync);
            if (pbSync != null) {
                pbSync.setVisibility(View.INVISIBLE);
            }
            InitLogin();
            strCurrentScreen = getString(R.string.app_name) +
                    ": V" + getString(R.string.app_version) +
                    ", Database: V" + String.valueOf(ufinDbHelper.DATABASE_VERSION);
            setAppActionbar();
        }
    }
