    public void UpdateMemberContactNumber(long lMemberID, String strContactNumber) {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        ContentValues values1 = new ContentValues();
        values1.put(ufinDbContract.MemberData.COLUMN_NAME_ContactNo, strContactNumber);
        String whereClause1 = ufinDbContract.MemberData.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(lMemberID) + "'";
        long lTemp1 = db.update(ufinDbContract.MemberData.TABLE_NAME, values1, whereClause1, null);
        if (lTemp1 > 0) {
            System.out.println("MemberData Updated with ContactNo.");
        }
        ContentValues values2 = new ContentValues();
        values2.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_ContactNumber, strContactNumber);
        String whereClause2 = ufinDbContract.PunarbhetSchedule.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(lMemberID) + "'";
        long lTemp2 = db.update(ufinDbContract.PunarbhetSchedule.TABLE_NAME, values2, whereClause2, null);
        if (lTemp2 > 0) {
            System.out.println("PunarbhetSchedule Updated with ContactNo.");
        }
        ContentValues values3 = new ContentValues();
        values3.put(ufinDbContract.MemberRecovery.COLUMN_NAME_PhoneNo, strContactNumber);
        String whereClause3 = ufinDbContract.MemberRecovery.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(lMemberID) + "'";
        long lTemp3 = db.update(ufinDbContract.MemberRecovery.TABLE_NAME, values3, whereClause3, null);
        if (lTemp3 > 0) {
            System.out.println("MemberRecovery Updated with ContactNo.");
        }

        db.close();
    }
