    public String SQLite_getMemberName(long actNumber) {
        String strName = "";

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.MemberData.COLUMN_NAME_Fname,
                ufinDbContract.MemberData.COLUMN_NAME_Mname,
                ufinDbContract.MemberData.COLUMN_NAME_Lname,
        };
        String selection1 = ufinDbContract.MemberData.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(actNumber) + "'";

        Cursor c1 = db.query(
                ufinDbContract.MemberData.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                null                                 // The sort order
        );

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    try {
                        strName = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_Fname));
                        strName = strName + " " + c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_Mname));
                        strName = strName + " " + c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberData.COLUMN_NAME_Lname));
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }

        return strName;
    }
