    public void SQLite_getPunarbhetVisitDetailsMaster() {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsID,
                ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsInMarathi,
                ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_ForDropdown,
                ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetails,
        };

        // How you want the results sorted in the resulting Cursor
        String sortOrder1 = ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_SequenceID + " ASC";

        Cursor c1 = db.query(
                ufinDbContract.PunarbhetVisitDetailsMatser.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                null,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        VisitDetailsIDMaster.clear();
        VisitDetailsInMarathiMaster.clear();
        VisitDetailsIDMaster.add(0);
        VisitDetailsInMarathiMaster.add("?");

        HomeLoanOfferVisitDetailsIDMaster.clear();
        HomeLoanOfferVisitDetailsInMarathiMaster.clear();
        HomeLoanOfferVisitDetailsIDMaster.add(0);
        HomeLoanOfferVisitDetailsInMarathiMaster.add("?");

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    try {
                        int iCount = c1.getCount();
                        for (int i = 0; i < iCount; i++) {
                            String Str2 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_ForDropdown));
                            if(Str2.equalsIgnoreCase("Yes")) {
                                String str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsInMarathi));
                                if (str1 == null) {
                                    str1 = "?";
                                }
                                String Str3 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetails));
                                if(Str3.equalsIgnoreCase("next loan required")) {
                                    VisitDetailsIDMaster.add(Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsID))));
                                    VisitDetailsInMarathiMaster.add(str1);
                                } else if(Str3.toLowerCase().contains("home loan")) {
                                    HomeLoanOfferVisitDetailsIDMaster.add(Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsID))));
                                    HomeLoanOfferVisitDetailsInMarathiMaster.add(str1);
                                } else {
                                    VisitDetailsIDMaster.add(Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsID))));
                                    VisitDetailsInMarathiMaster.add(str1);
                                    HomeLoanOfferVisitDetailsIDMaster.add(Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetVisitDetailsMatser.COLUMN_NAME_VisitDetailsID))));
                                    HomeLoanOfferVisitDetailsInMarathiMaster.add(str1);
                                }
                            }
                            c1.moveToNext();
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }
    }
