    public void SQLite_getRelationMaster() {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.RelationMaster.COLUMN_NAME_RelationID,
                ufinDbContract.RelationMaster.COLUMN_NAME_Description,
                ufinDbContract.RelationMaster.COLUMN_NAME_MarathiDescription,
                ufinDbContract.RelationMaster.COLUMN_NAME_SequenceID,
        };
        String Active = "1";

        String selection1 = ufinDbContract.RelationMaster.COLUMN_NAME_IsActive + "=" + "'" + Active + "'";

        // How you want the results sorted in the resulting Cursor
        String sortOrder1 = ufinDbContract.RelationMaster.COLUMN_NAME_SequenceID + " ASC";

        Cursor c1 = db.query(
                ufinDbContract.RelationMaster.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        RelationIDMaster.clear();
        RelationMarathiDescriptionMaster.clear();
        RelationIDMaster.add(0);
        RelationMarathiDescriptionMaster.add("");

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    try {
                        int iCount = c1.getCount();
                        for (int i = 0; i < iCount; i++) {
                            RelationIDMaster.add(Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.RelationMaster.COLUMN_NAME_RelationID))));
                            String str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.RelationMaster.COLUMN_NAME_MarathiDescription));
                            if (str1 == null) {
                                str1 = "?";
                            }
                            RelationMarathiDescriptionMaster.add(str1);
                            String str2 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.RelationMaster.COLUMN_NAME_Description));
                            if(str2.equalsIgnoreCase("Main Member")) {
                                RelationIDMainMember = RelationIDMaster.get(RelationIDMaster.size() - 1);
                            }
                            if(str2.equalsIgnoreCase("Spouse")) {
                                RelationIDSpouse = RelationIDMaster.get(RelationIDMaster.size() - 1);
                            }
                            c1.moveToNext();
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }
    }
    public boolean SQLite_saveAddress(clsMemberAddress newAddress, long TimeInMillis, boolean syncRecord) {
        boolean Status = false;

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        try {
            Calendar cal = Calendar.getInstance();
            if (TimeInMillis > 0)
                cal.setTimeInMillis(TimeInMillis);
            Date date = cal.getTime();
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.ENGLISH);
            String strTimeStamp = sdf.format(date);// all done

            ContentValues values1 = new ContentValues();
            values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_Address, newAddress.Address);
            values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_DistrictID, newAddress.DistrictID);
            values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_Pincode, newAddress.Pincode);
            values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_DigiPin, newAddress.DigiPin);
            values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_IsActive, newAddress.IsActive);

            JSONObject postDataParams = new JSONObject();
            if(syncRecord) {
                try {
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_Address, newAddress.Address);
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_DistrictID, newAddress.DistrictID);
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_Pincode, newAddress.Pincode);
//bmp 21-Aug-25
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_DigiPin, newAddress.DigiPin);
//bmp 21-Aug-25
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_IsActive, newAddress.IsActive);
                    postDataParams.put("LSO_ID", LSO_ID);
                    postDataParams.put("Org_ID", OrgID);
                } catch (JSONException e) {
                    e.printStackTrace();
                }
            }
            long lTemp1 = 0;
            ContentValues values2 = new ContentValues();
            String StrNewRecord = "";
            String StrReady = "";
            if (newAddress.AddressID > 0) {
                String whereClause = ufinDbContract.MemberAddress.COLUMN_NAME_AddressID + "=" + "'" + String.valueOf(newAddress.AddressID) + "'";
                lTemp1 = db.update(ufinDbContract.MemberAddress.TABLE_NAME, values1, whereClause, null);
                if (lTemp1 > 0) {
                    System.out.println("newAddress Updated.");
                    StrNewRecord = "False";
                    StrReady = "True";
                }
            } else {
                SimpleDateFormat sdf2 = new SimpleDateFormat("MMddHHmmss", Locale.ENGLISH);
                String Str1 = sdf2.format(date) + String.format("%08d", LSO_ID);
                Str1 = Str1.replaceFirst("^0+(?!$)", "");
                try {
                    newAddress.AddressID = Long.parseLong(Str1);
                } catch (NumberFormatException e) {
                    e.printStackTrace();
                }
                values1.put(ufinDbContract.MemberAddress.COLUMN_NAME_AddressID, newAddress.AddressID);
                lTemp1 = db.insert(ufinDbContract.MemberAddress.TABLE_NAME, null, values1);
                if (lTemp1 > 0) {
                    System.out.println("address Inserted.");
                    StrNewRecord = "True";
                    StrReady = "True";
                }
            }

            if(syncRecord) {
                String strDataParamsQuery = "";
                try {
                    postDataParams.put(ufinDbContract.MemberAddress.COLUMN_NAME_AddressID, newAddress.AddressID);

                    StringBuilder sb = new StringBuilder();
                    Iterator<String> keys = postDataParams.keys();
                    sb.append("?"); //start of query args
                    while (keys.hasNext()) {
                        String key = keys.next();
                        sb.append(key);
                        sb.append("=");
                        sb.append(postDataParams.get(key));
                        sb.append("&"); //To allow for another argument.
                    }
                    strDataParamsQuery = sb.toString();
                    strDataParamsQuery = strDataParamsQuery.substring(0, (strDataParamsQuery.length() - 1));
                    strDataParamsQuery = strDataParamsQuery.replaceAll(" ", "%20");
                } catch (JSONException e) {
                    e.printStackTrace();
                }

                if (!StrNewRecord.isEmpty()) {
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID, strTimeStamp);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName, ufinDbContract.MemberAddress.TABLE_NAME);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID, newAddress.AddressID);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsNewRecord, StrNewRecord);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsReady, StrReady);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_PostDataParams, strDataParamsQuery);

                    lTemp1 = db.insert(ufinDbContract.RecordsToSync.TABLE_NAME, null, values2);
                    if (lTemp1 > 0) {
                        clsRecordsToSync newRec = new clsRecordsToSync();
                        newRec.SyncID = strTimeStamp;
                        newRec.recordID = newAddress.AddressID;
                        newRec.recordInserted = StrNewRecord.equalsIgnoreCase("True");
                        newRec.recordReady = StrReady.equalsIgnoreCase("True");
                        newRec.PostParams = strDataParamsQuery;
                        SyncMemberAddress.add(newRec);
//bmp 18-Feb-23
                        File packetFile = new File(baseDir + "/config/" + strPacketFile);
                        try {
                            BufferedWriter bwr = new BufferedWriter(new FileWriter(packetFile, true));
                            bwr.newLine();
                            bwr.newLine();
                            bwr.write(strDataParamsQuery);
                            bwr.flush();
                            bwr.close();
                        } catch (IOException e) {
                            e.printStackTrace();
                        }
//bmp 18-Feb-23

                        System.out.println("RecordsToSync Updated.");
                        Status = true;
                    }
                }
            }
        } finally {
            db.close();
        }

        return Status;
    }
    public void SQLite_getAddress(clsMemberAddress newAddress) {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.MemberAddress.COLUMN_NAME_Address,
                ufinDbContract.MemberAddress.COLUMN_NAME_DistrictID,
                ufinDbContract.MemberAddress.COLUMN_NAME_Pincode,
                ufinDbContract.MemberAddress.COLUMN_NAME_DigiPin,
                ufinDbContract.MemberAddress.COLUMN_NAME_IsActive,
                ufinDbContract.MemberAddress.COLUMN_NAME_AddressID,
        };

        String selection1 = ufinDbContract.MemberAddress.COLUMN_NAME_IsActive + "=" + "'" + String.valueOf(1) + "'"
                + " and " + ufinDbContract.MemberAddress.COLUMN_NAME_AddressID + "=" + "'" + String.valueOf(newAddress.AddressID) + "'";

        // How you want the results sorted in the resulting Cursor
        String sortOrder1 = ufinDbContract.MemberAddress.COLUMN_NAME_AddressID + " DESC";

        Cursor c1 = db.query(
                ufinDbContract.MemberAddress.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    try {
                        try {
                            newAddress.IsActive = Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_IsActive)));
                        } catch (NumberFormatException e) {
                            String Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_IsActive));
                            if ((Str1 == null) || (Str1.equalsIgnoreCase("null")) || (Str1.equalsIgnoreCase("true")))
                                newAddress.IsActive = 1;
                            else
                                newAddress.IsActive = 0;
                        }

                        String Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_Address));
                        if ((Str1 == null) || (Str1.equalsIgnoreCase("null")))
                            newAddress.Address = "NA";
                        else if (!Str1.isEmpty())
                            newAddress.Address = Str1;
                        else
                            newAddress.Address = "NA";

                        Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_DistrictID));
                        if ((Str1 == null) || (Str1.equalsIgnoreCase("null")))
                            newAddress.DistrictID = "NA";
                        else if (!Str1.isEmpty())
                            newAddress.DistrictID = Str1;
                        else
                            newAddress.DistrictID = "NA";

                        Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_Pincode));
                        if ((Str1 == null) || (Str1.equalsIgnoreCase("null")))
                            newAddress.Pincode = "NA";
                        else if (!Str1.isEmpty())
                            newAddress.Pincode = Str1;
                        else
                            newAddress.Pincode = "NA";

                        Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_DigiPin));
                        if ((Str1 == null) || (Str1.equalsIgnoreCase("null")))
                            newAddress.DigiPin = "NA";
                        else if (!Str1.isEmpty())
                            newAddress.DigiPin = Str1;
                        else
                            newAddress.DigiPin = "NA";

                        try {
                            newAddress.AddressID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberAddress.COLUMN_NAME_AddressID)));
                        } catch (NumberFormatException e) {
                            newAddress.AddressID = 0;
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }
    }
