    public void SQLite_getMemberImpactAnswer(long actNumber) {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberFamilyDetailsID,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IPAnswerID,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_EncodedBy,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactEncodedDate,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_UpdatedBy,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactUpdatedDate,
                ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IsActive,
        };

        //We have to get All MemberImpactAnswer entries for the Member including IsActive = 0 => required for checkboxes
        String selection1 = ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberFamilyDetailsID + "=" + "'" + String.valueOf(actNumber) + "'";

        // How you want the results sorted in the resulting Cursor
        String sortOrder1 = ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID + " DESC";

        Cursor c1 = db.query(
                ufinDbContract.MemberImpactAnswer.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        MemberImpactAnswer.clear();
        tMemberImpactAnswer.clear();
        String strDate = "";

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    int iCount = c1.getCount();
                    for (int i = 0; i < iCount; i++) {
                        clsMemberImpactAnswer newAnswer = new clsMemberImpactAnswer();
                        newAnswer.Init_MemberImpactAnswer();

                        try {
                            newAnswer.MemberImpactAnswerID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID)));
                        } catch (NumberFormatException e) {
                            newAnswer.MemberImpactAnswerID = 0;
                        }
                        try {
                            newAnswer.MemberFamilyDetailsID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberFamilyDetailsID)));
                        } catch (NumberFormatException e) {
                            newAnswer.MemberFamilyDetailsID = 0;
                        }
                        try {
                            newAnswer.IPAnswerID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IPAnswerID)));
                        } catch (NumberFormatException e) {
                            newAnswer.IPAnswerID = 0;
                        }
                        String Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactEncodedDate));
                        if ((Str1 == null) || (Str1.equalsIgnoreCase("null")))
                            newAnswer.ImpactEncodedDate = "NA";
                        else if (!Str1.isEmpty())
                            newAnswer.ImpactEncodedDate = Str1.substring(0, 10);
                        else
                            newAnswer.ImpactEncodedDate = "NA";

                        try {
                            newAnswer.IsActive = Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IsActive)));
                        } catch (NumberFormatException e) {
                            Str1 = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IsActive));
                            if ((Str1 == null) || (Str1.equalsIgnoreCase("null")) || (Str1.equalsIgnoreCase("true")))
                                newAnswer.IsActive = 1;
                            else
                                newAnswer.IsActive = 0;
                        }

                        //To display Impact parameters for BM login
                        boolean bExists = false;
                        for (int k = 0; k < MemberImpactAnswer.size(); k++) {
                            if (MemberImpactAnswer.get(k).IPAnswerID == newAnswer.IPAnswerID) {
                                bExists = true;
                            }
                        }
                        if (!bExists) {
                            MemberImpactAnswer.add(newAnswer);
                            clsMemberImpactAnswer tnewAnswer = new clsMemberImpactAnswer();
                            newAnswer.Copy_MemberImpactAnswer(tnewAnswer);
                            tMemberImpactAnswer.add(tnewAnswer);
                        }

                        c1.moveToNext();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }
    }
    public boolean SQLite_saveMemberImpactAnswer(clsMemberImpactAnswer answer, long TimeInMillis, boolean syncRecord) {
        boolean Status = false;

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        try {
            Calendar cal = Calendar.getInstance();
            if (TimeInMillis > 0)
                cal.setTimeInMillis(TimeInMillis);
            Date date = cal.getTime();
//bmp 11-Apr-23
//        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.ENGLISH);
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.ENGLISH);
//bmp 11-Apr-23
            String strTimeStamp = sdf.format(date);// all done
            answer.EncodedBy = UserID;
            answer.ImpactEncodedDate = strTimeStamp;
            answer.UpdatedBy = 0;
            answer.ImpactUpdatedDate = strTimeStamp;    //Mandatory field as per API

            ContentValues values1 = new ContentValues();
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberFamilyDetailsID, answer.MemberFamilyDetailsID);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IPAnswerID, answer.IPAnswerID);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_EncodedBy, answer.EncodedBy);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactEncodedDate, answer.ImpactEncodedDate);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_UpdatedBy, answer.UpdatedBy);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactUpdatedDate, answer.ImpactUpdatedDate);
            values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IsActive, answer.IsActive);

            JSONObject postDataParams = new JSONObject();

            if(syncRecord) {
                try {
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberFamilyDetailsID, answer.MemberFamilyDetailsID);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IPAnswerID, answer.IPAnswerID);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_EncodedBy, answer.EncodedBy);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactEncodedDate, answer.ImpactEncodedDate);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_UpdatedBy, answer.UpdatedBy);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_ImpactUpdatedDate, answer.ImpactUpdatedDate);
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_IsActive, answer.IsActive);

                    postDataParams.put("LSO_ID", LSO_ID);
                    postDataParams.put("Org_ID", OrgID);
                } catch (JSONException e) {
                    e.printStackTrace();
                }
            }
            long lTemp1 = 0;
            ContentValues values2 = new ContentValues();
            String StrNewRecord = "";
            String StrReady = "";
            if (answer.MemberImpactAnswerID > 0) {
                String whereClause = ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID + "=" + "'" + String.valueOf(answer.MemberImpactAnswerID) + "'";
                lTemp1 = db.update(ufinDbContract.MemberImpactAnswer.TABLE_NAME, values1, whereClause, null);
                if (lTemp1 > 0) {
                    if (lTemp1 > 1) {
                        System.out.println("?????????? Multiple MemberImpactAnswer Records Updated.");
                    }
                    System.out.println("MemberImpactAnswer Updated.");
                    StrNewRecord = "False";
                    StrReady = "True";
                }
            } else {
                SimpleDateFormat sdf2 = new SimpleDateFormat("MMddHHmmss", Locale.ENGLISH);
                String Str1 = sdf2.format(date) + String.format("%08d", LSO_ID);
                Str1 = Str1.replaceFirst("^0+(?!$)", "");
                try {
                    answer.MemberImpactAnswerID = Long.parseLong(Str1);
                } catch (NumberFormatException e) {
                    e.printStackTrace();
                }
                values1.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID, answer.MemberImpactAnswerID);
                lTemp1 = db.insert(ufinDbContract.MemberImpactAnswer.TABLE_NAME, null, values1);
                if (lTemp1 > 0) {
                    System.out.println("MemberImpactAnswer Inserted.");
                    StrNewRecord = "True";
                    StrReady = "True";
                }
            }

            if(syncRecord) {
                String strDataParamsQuery = "";
                try {
                    postDataParams.put(ufinDbContract.MemberImpactAnswer.COLUMN_NAME_MemberImpactAnswerID, answer.MemberImpactAnswerID);

                    StringBuilder sb = new StringBuilder();
                    Iterator<String> keys = postDataParams.keys();
                    sb.append("?"); //start of query args
                    while (keys.hasNext()) {
                        String key = keys.next();
                        sb.append(key);
                        sb.append("=");
                        sb.append(postDataParams.get(key));
                        sb.append("&"); //To allow for another argument.
                    }
                    strDataParamsQuery = sb.toString();
                    strDataParamsQuery = strDataParamsQuery.substring(0, (strDataParamsQuery.length() - 1));
                    strDataParamsQuery = strDataParamsQuery.replaceAll(" ", "%20");
                } catch (JSONException e) {
                    e.printStackTrace();
                }

                if (!StrNewRecord.isEmpty()) {
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID, strTimeStamp);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName, ufinDbContract.MemberImpactAnswer.TABLE_NAME);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID, answer.MemberImpactAnswerID);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsNewRecord, StrNewRecord);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsReady, StrReady);
                    values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_PostDataParams, strDataParamsQuery);

                    lTemp1 = db.insert(ufinDbContract.RecordsToSync.TABLE_NAME, null, values2);
                    if (lTemp1 > 0) {
                        clsRecordsToSync newRec = new clsRecordsToSync();
                        newRec.SyncID = strTimeStamp;
                        newRec.recordID = answer.MemberImpactAnswerID;
                        newRec.recordInserted = StrNewRecord.equalsIgnoreCase("True");
                        newRec.recordReady = StrReady.equalsIgnoreCase("True");
                        newRec.PostParams = strDataParamsQuery;
                        SyncMemberImpactAnswer.add(newRec);
//bmp 18-Feb-23
                        File packetFile = new File(baseDir + "/config/" + strPacketFile);
                        try {
                            BufferedWriter bwr = new BufferedWriter(new FileWriter(packetFile, true));
                            bwr.newLine();
                            bwr.newLine();
                            bwr.write(strDataParamsQuery);
                            bwr.flush();
                            bwr.close();
                        } catch (IOException e) {
                            e.printStackTrace();
                        }
//bmp 18-Feb-23

                        System.out.println("RecordsToSync Updated.");
                        Status = true;
                    }
                }
            }
        } finally {
            db.close();
        }

        return Status;
    }
