    public void SQLite_getDocumentPhotos(long actNumber) {
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();
        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.DocumentPhoto.COLUMN_NAME_DocumentPhotoID,
                ufinDbContract.DocumentPhoto.COLUMN_NAME_MemberDocuemntsRcvdID,
                ufinDbContract.DocumentPhoto.COLUMN_NAME_GroupID,
                ufinDbContract.DocumentPhoto.COLUMN_NAME_IsActive,
                ufinDbContract.DocumentPhoto.COLUMN_NAME_MemberDocumentsID,
        };
        String selection1 = ufinDbContract.DocumentPhoto.COLUMN_NAME_MemberDocuemntsRcvdID + "=" + "'" + String.valueOf(actNumber) + "'";

        // How you want the results sorted in the resulting Cursor
        String sortOrder1 = ufinDbContract.DocumentPhoto.COLUMN_NAME_DocumentPhotoID + " DESC";

        Cursor c1 = db.query(
                ufinDbContract.DocumentPhoto.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    int iCount = c1.getCount();
                    for (int i = 0; i < iCount; i++) {
                        clsDocumentPhoto newDocPhoto = new clsDocumentPhoto();
                        newDocPhoto.Init_DocumentPhoto();
                        try {
                            newDocPhoto.DocumentPhotoID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.DocumentPhoto.COLUMN_NAME_DocumentPhotoID)));
                        } catch (NumberFormatException e) {
                            newDocPhoto.DocumentPhotoID = 0;
                        }
                        try {
                            newDocPhoto.MemberDocuemntsRcvdID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.DocumentPhoto.COLUMN_NAME_MemberDocuemntsRcvdID)));
                        } catch (NumberFormatException e) {
                            newDocPhoto.MemberDocuemntsRcvdID = 0;
                        }
                        try {
                            newDocPhoto.GroupID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.DocumentPhoto.COLUMN_NAME_GroupID)));
                        } catch (NumberFormatException e) {
                            newDocPhoto.GroupID = 0;
                        }
                        try {
                            newDocPhoto.MemberDocumentsID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.DocumentPhoto.COLUMN_NAME_MemberDocumentsID)));
                        } catch (NumberFormatException e) {
                            newDocPhoto.MemberDocumentsID = 0;
                        }
                        try {
                            newDocPhoto.IsActive = Integer.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.DocumentPhoto.COLUMN_NAME_IsActive)));
                        } catch (NumberFormatException e) {
                            newDocPhoto.IsActive = 0;
                        }

                        DocumentPhotos.add(newDocPhoto);
                        clsDocumentPhoto tnewDocPhoto = new clsDocumentPhoto();
                        newDocPhoto.Copy_DocumentPhoto(tnewDocPhoto);
                        tDocumentPhotos.add(tnewDocPhoto);

                        c1.moveToNext();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }
    }
