                    postDataParams.put(ufinDbContract.NewGroupInfo.COLUMN_NAME_LoanDisbursementDate, newgroupinfo.LoanDisbursementDate);
                    postDataParams.put(ufinDbContract.NewGroupInfo.COLUMN_NAME_LoanDisbursementTime, newgroupinfo.LoanDisbursementTime);

                    postDataParams.put(ufinDbContract.NewGroupInfo.COLUMN_NAME_LoanRepayInstallmentDate, newgroupinfo.LoanRepayInstallmentDate);
                    postDataParams.put(ufinDbContract.NewGroupInfo.COLUMN_NAME_LoanRepayInstallmentTime, newgroupinfo.LoanRepayInstallmentTime);

