    public long SQLite_SearchPromotionList(String strName) {
        long lMemberID = 0;
        // Gets the data repository in read mode
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        SQLiteDatabase db = mDbHelper.getReadableDatabase();
        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.PunarbhetSchedule.COLUMN_NAME_MemberID,
        };
        String selection1 = ufinDbContract.PunarbhetSchedule.COLUMN_NAME_MemberName + "=" + "'" + strName + "'";
        Cursor c1 = db.query(
                ufinDbContract.PunarbhetSchedule.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                null                                 // The sort order
        );
        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    int Count = c1.getCount();
                    try {
                        for (int i = 0; i < Count; i++) {
                            lMemberID = Long.valueOf(c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_MemberID)));
                            c1.moveToNext();
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }

        return lMemberID;
    }
