            lTemp1 = db.update(ufinDbContract.PunarbhetSchedule.TABLE_NAME, values1, whereClause, null);
            if (lTemp1 > 0) {
            } else {
                lTemp1 = db.insert(ufinDbContract.PunarbhetSchedule.TABLE_NAME, null, values1);
                if (lTemp1 > 0) {
                }
            }
