    public boolean GetCBStatus(String strServerIP) {
        HttpURLConnection urlConnection = null;
        boolean Status = false;
        URL url = null;
        System.out.println("GetCBStatus");

        for(int i=0; i<SyncCBStatus.size(); i++) {
            try {
                String Str1 = SyncCBStatus.get(i).PostParams;
//bmp 22-Apr-26
//                url = new URL("http://" + strServerIP + ":" + strServerPort + URL_GetCBStatus + Str1);
                String strUrl = "http://" + strServerIP + ":" + strServerPort + URL_GetCBStatus + Str1;
                url = new URL(strUrl);
//bmp 22-Apr-26

                Calendar cal = Calendar.getInstance();
                long msecQueryTime = cal.getTimeInMillis();
                msecResponseTime = msecHttpURLConnectionTimeout;

                urlConnection = (HttpURLConnection) url.openConnection();
                urlConnection.setReadTimeout(msecHttpURLConnectionTimeout /* milliseconds */);
                urlConnection.setConnectTimeout(msecHttpURLConnectionTimeout /* milliseconds */);
                urlConnection.setRequestMethod("GET");

                urlConnection.setUseCaches(false);
                //            urlConnection.setDoOutput(true);
                urlConnection.setDoInput(true);
                urlConnection.setChunkedStreamingMode(0);

                String strResponse = "URL: " + strUrl + "\n" + "Response: ";

                int responseCode = urlConnection.getResponseCode();
                cal = Calendar.getInstance();
                msecResponseTime = cal.getTimeInMillis() - msecQueryTime;
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    InputStream in = new BufferedInputStream(urlConnection.getInputStream());
                    BufferedReader br = new BufferedReader(new InputStreamReader(in));
                    String strOutput;
                    int iDownloadBytes = 0;
                    while ((strOutput = br.readLine()) != null) {
                        iDownloadBytes = iDownloadBytes + strOutput.length();
//bmp 22-Apr-26
                        strResponse = strResponse + strOutput;
//bmp 22-Apr-26
                        if( (strOutput.equalsIgnoreCase("[]")) || (strOutput.equalsIgnoreCase("<html>")) ) {
                            Status = true;
                            break;
                        }
                        //For correct extraction of float value from JSONArray
                        strOutput = strOutput.replace(".00", "");
                        //For correct extraction of Long value from JSONArray
                        strOutput = strOutput.replace(".0", "");
                        JSONArray jsonArray = null;
                        try {
                            jsonArray = new JSONArray(strOutput);
                            int iCount = jsonArray.length();
                            int iCount2 = 0;
                            if (iCount > 0) {
                                ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                                try {
                                    for (iCount2 = 0; iCount2 < iCount; iCount2++) {
                                        long lTemp1 = 0;
                                        String strLastLoanStatus = "";
                                        String strEnquiryDate = "";
                                        int iCBScore = -1;
                                        int iActiveLoans = -1;
                                        int iTotalLoanBalance = -1;
                                        String strCBStatus = "";
                                        int iCBCheck = -1;
                                        long lMemberID = -1;
                                        String strCBRemark = "";
                                        JSONObject tableRow = null;
                                        try {
                                            tableRow = (JSONObject) jsonArray.get(iCount2);
                                            try {
                                                lMemberID = tableRow.getLong("MemberID");
                                            } catch (Exception e) {
                                                lMemberID = SyncCBStatus.get(i).recordID;
                                            }
                                            strLastLoanStatus = tableRow.getString("LastLoanStatus");
                                            strEnquiryDate = tableRow.getString("Checked_Date");
                                            strCBRemark = tableRow.getString("Remark");
//bmp 16-Apr-26
//                                            iCBScore = tableRow.getInt("CBScore");
//bmp 16-Apr-26
                                            iActiveLoans = tableRow.getInt("NoOfActiveLoans");
                                            iTotalLoanBalance = tableRow.getInt("TotalLoanBalance");
                                            strCBStatus = tableRow.getString("CBStatus");
                                            if(strCBStatus.equalsIgnoreCase("OK")) {
                                                iCBCheck = 1;
                                            } else if(strCBStatus.equalsIgnoreCase("Reject")) {
                                                iCBCheck = 0;
                                            }

                                            if(iCBCheck >= 0) {
                                                // Gets the data repository in write mode
                                                SQLiteDatabase db = mDbHelper.getWritableDatabase();
                                                try {
                                                    ContentValues values = new ContentValues();
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_CreditBureauCheck, iCBCheck);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_CBTotalLoanBalance, iTotalLoanBalance);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_CBNoOfActiveLoans, iActiveLoans);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_CBScore, iCBScore);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_CBRemark, strCBRemark);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_EnquiryDate, strEnquiryDate);
                                                    values.put(ufinDbContract.PunarbhetSchedule.COLUMN_NAME_LastLoanStatus, strLastLoanStatus);
                                                    String whereClause = ufinDbContract.PunarbhetSchedule.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(lMemberID) + "'";
                                                    lTemp1 = db.update(ufinDbContract.PunarbhetSchedule.TABLE_NAME, values, whereClause, null);
                                                    if (lTemp1 > 0) {
                                                        String whereClause2 = ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName + "=" + "'" + "CBStatus" + "'" +
                                                                " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID + "=" + "'" + SyncCBStatus.get(i).SyncID + "'" +
                                                                " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID + "=" + "'" + String.valueOf(lMemberID) + "'";
                                                        long lTemp2 = 0;
                                                        lTemp2 = db.delete(ufinDbContract.RecordsToSync.TABLE_NAME, whereClause2, null);
                                                        if (lTemp2 > 0) {
                                                            SyncCBStatus.remove(i);
                                                            i = i - 1;  //avoid skipping entries by adjusting for i++
                                                        }
                                                    }
                                                } finally {
                                                    db.close();
                                                }
                                            }
                                        } catch (JSONException e) {
                                            throw new RuntimeException(e);
                                        }
                                    }
                                    if(iCount2 > 0)
                                        Status = true;
                                } catch (Exception e) {
                                    System.out.println(e.getMessage());
                                }
                            }
                        } catch (JSONException e) {
                            throw new RuntimeException(e);
                        }
                    }
                    cal = Calendar.getInstance();
                    long msecDownloadTime = cal.getTimeInMillis() - msecQueryTime;
                    downloadKBPS = (int) (iDownloadBytes / msecDownloadTime);
//bmp 22-Apr-26
                    Date date = cal.getTime();
                    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.ENGLISH);
                    String strTimeStamp = sdf.format(date);// all done
                    String strVersion = getString(R.string.app_name) + ": V" + getString(R.string.app_version);
                    strResponse = strResponse + "\n" + strVersion + " Timestamp: " + strTimeStamp;
                    if(Status) {
                        ResponseUrl.add(strResponse);
                    } else {
                        DebugUrl.add(strResponse);
                    }
//bmp 22-Apr-26
                }
                urlConnection.disconnect();
            } catch (Exception e) {
                e.printStackTrace();
                if (urlConnection != null)
                    urlConnection.disconnect();
            }
        }
        return Status;
    }
