//bmp 30-Mar-26
//    private void CheckDuplicateFamilyMembers() {
    private void CheckDuplicateFamilyMembers(String strListType) {
//bmp 30-Mar-26
        //Verify and Update Deletion Reason ID to deactive, duplicate family members
        for(int i=1; i<Member.size(); i++) {
            if((Member.get(i).IsActive == 0) && (Member.get(i).DeletionReasonID == 0)) {
                boolean flagDuplicateEntryFound = false;
                for(int j=0; j<Member.size(); j++) {
                    if(i == j)
                        continue;
                    if(Member.get(i).Fname.equalsIgnoreCase(Member.get(j).Fname)) {
                        flagDuplicateEntryFound = true;
                        if(Member.get(j).IsActive == 1) {
                            //Active entry of same member found,
                            //Update DeletionReasonID to Deactive entry of same member.
                            if(OrgID == 1) {
                                Member.get(i).DeletionReasonID = clsMemberData.DELETION_REASON_ID_DUPLICATE_MEMBER_ORGID_1;
                            } else {
                                Member.get(i).DeletionReasonID = clsMemberData.DELETION_REASON_ID_DUPLICATE_MEMBER_ORGID_2;
                            }
                            LastTimeInMillis += 1000;
                            if(SQLite_saveMember(Member.get(i), LastTimeInMillis, true)) {
                                Member.get(i).Copy_Memberdata(tMember.get(i));
                            }
                            break;
                        } else {
                            //Another Deactive entry of same member.
                            //Need to review and update on server.
                            System.out.println(Member.get(i).Fname);
                        }
                    }
                }
                if(!flagDuplicateEntryFound) {
                    //Only one entry of the member found,
//bmp 30-Mar-26
                    //White-II is Deactive member list, show all the family members,
                    //and let LSO decide.
                    if(!strListType.equalsIgnoreCase("White-II")) {
//bmp 30-Mar-26
                        //Update DeletionReasonID to Deactive entry of the member.
                        if (OrgID == 1) {
                            Member.get(i).DeletionReasonID = clsMemberData.DELETION_REASON_ID_DUPLICATE_MEMBER_ORGID_1;
                        } else {
                            Member.get(i).DeletionReasonID = clsMemberData.DELETION_REASON_ID_DUPLICATE_MEMBER_ORGID_2;
                        }
                        LastTimeInMillis += 1000;
                        if (SQLite_saveMember(Member.get(i), LastTimeInMillis, true)) {
                            Member.get(i).Copy_Memberdata(tMember.get(i));
                        }
//bmp 30-Mar-26
                    }
//bmp 30-Mar-26
                }
            }
        }
    }
