//    private void GetMemberInfo() {
    private void GetMemberInfo(String strListType) {
//bmp 30-Mar-26
        SQLite_getMembers(selectedMemberID, "MemberID");
        if(Member.size() > 0) {
            SQLite_getMemberOtherMFIData(Member.get(0).MemberID);

            SQLite_getMemberOrgDetails(Member.get(0).GroupID);
            SQLite_getMembers(Member.get(0).MemberID, "MainMemberID");

            //Verify and Update Deletion Reason ID to deactive, duplicate family members
//bmp 30-Mar-26
//            CheckDuplicateFamilyMembers();
            CheckDuplicateFamilyMembers(strListType);
//bmp 30-Mar-26
            //Reload Member Info
            SQLite_getMembers(selectedMemberID, "MemberID");
            SQLite_getMembers(Member.get(0).MemberID, "MainMemberID");
//bmp 09-Feb-26
            for(int i=0; i<Member.size(); i++) {
                SQLite_getPersonalImpactInfo(Member.get(i).MemberID);
//bmp 04-Mar-25
                if(PersonalImpactInfo.size() < (i+1)) {
                    //Missing PersonalImpactInfo record for Member.get(i).MemberID
                    clsPersonalImpactInfo newPersonalImpactInfo = new clsPersonalImpactInfo();
                    newPersonalImpactInfo.Init_PersonalImpactInfo();
                    newPersonalImpactInfo.MemberID = Member.get(i).MemberID;
                    newPersonalImpactInfo.UpdatedBy = UserID;
                    PersonalImpactInfo.add(newPersonalImpactInfo);
                    clsPersonalImpactInfo tnewPersonalImpactInfo = new clsPersonalImpactInfo();
                    newPersonalImpactInfo.Copy_PersonalImpactInfo(tnewPersonalImpactInfo);
                    tPersonalImpactInfo.add(tnewPersonalImpactInfo);
                }
//bmp 04-Mar-25
//bmp 10-Mar-25
                if(PersonalImpactInfo.size() > (i+1)) {
                    //Duplicate PersonalImpactInfo records for Member.get(i).MemberID
                    if(Member.get(i).IsActive == 0) {
                        //Deactivate all Duplicate PersonalImpactInfo records
                        for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                            if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
                                continue;
                            if (PersonalImpactInfo.get(k).IsActive == 1) {
                                PersonalImpactInfo.get(k).IsActive = 0;
                                LastTimeInMillis += 1000;
                                SQLite_savePersonalImpactInfo(PersonalImpactInfo.get(k), 0, false);
                            }
                        }
                        //Retain only 1 Deactive record...
                        int iIndex = -1;
                        for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                            if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
                                continue;
                            iIndex = k;
                            break;
                        }
                        ArrayList<Long> alMarkForDelete = new ArrayList<Long>();
                        alMarkForDelete.clear();
                        for (int k = (iIndex+1); k < PersonalImpactInfo.size(); k++) {
                            //...and Delete all but 1 Duplicate PersonalImpactInfo records
                            alMarkForDelete.add(PersonalImpactInfo.get(k).MemberDetailsForImpactID);
                            ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                            SQLiteDatabase dbInt = mDbHelper.getWritableDatabase();
                            try {
                                String whereClause = ufinDbContract.PersonalImpactInfo.COLUMN_NAME_MemberDetailsForImpactID + "=" + "'" + String.valueOf(PersonalImpactInfo.get(k).MemberDetailsForImpactID) + "'";
                                dbInt.delete(ufinDbContract.PersonalImpactInfo.TABLE_NAME, whereClause, null);
                            } finally {
                                dbInt.close();
                            }
                        }
                        //..and remove deleted records from PersonalImpactInfo ArrayList
                        for (int m = 0; m < alMarkForDelete.size(); m++) {
                            for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                                if(alMarkForDelete.get(m) == PersonalImpactInfo.get(k).MemberDetailsForImpactID) {
                                    PersonalImpactInfo.remove(k);
                                    tPersonalImpactInfo.remove(k);
                                    break;
                                }
                            }
                        }
                    } else {
                        //search for Active record in PersonalImpactInfo ArrayList
                        int iIndex = -1;
                        for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                            if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
                                continue;
                            if (PersonalImpactInfo.get(k).IsActive == 1) {
                                iIndex = k;
                            }
                        }
                        if (iIndex < 0) {
                            //No Active record found in PersonalImpactInfo ArrayList...
                            boolean flagOne = true;
                            for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                                if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
                                    continue;
                                //...mark one record as active...
                                PersonalImpactInfo.get(k).IsActive = 1;
                                LastTimeInMillis += 1000;
                                SQLite_savePersonalImpactInfo(PersonalImpactInfo.get(k), 0, false);
                                iIndex = k;
                                break;
                            }
                            ArrayList<Long> alMarkForDelete = new ArrayList<Long>();
                            alMarkForDelete.clear();
                            for (int k = (iIndex + 1); k < PersonalImpactInfo.size(); k++) {
                                //...and Delete all but 1 Duplicate PersonalImpactInfo records
                                alMarkForDelete.add(PersonalImpactInfo.get(k).MemberDetailsForImpactID);
                                ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                                SQLiteDatabase dbInt = mDbHelper.getWritableDatabase();
                                try {
                                    String whereClause = ufinDbContract.PersonalImpactInfo.COLUMN_NAME_MemberDetailsForImpactID + "=" + "'" + String.valueOf(PersonalImpactInfo.get(k).MemberDetailsForImpactID) + "'";
                                    dbInt.delete(ufinDbContract.PersonalImpactInfo.TABLE_NAME, whereClause, null);
                                } finally {
                                    dbInt.close();
                                }
                            }
                            //..and remove deleted records from PersonalImpactInfo ArrayList
                            for (int m = 0; m < alMarkForDelete.size(); m++) {
                                for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                                    if (alMarkForDelete.get(m) == PersonalImpactInfo.get(k).MemberDetailsForImpactID) {
                                        PersonalImpactInfo.remove(k);
                                        tPersonalImpactInfo.remove(k);
                                        break;
                                    }
                                }
                            }
                        } else {
                            //One Active record found in PersonalImpactInfo ArrayList...
                            ArrayList<Long> alMarkForDelete = new ArrayList<Long>();
                            alMarkForDelete.clear();
                            for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                                if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
                                    continue;
                                if (k != iIndex) {
                                    //...Delete all Deactive Duplicate PersonalImpactInfo records
                                    alMarkForDelete.add(PersonalImpactInfo.get(k).MemberDetailsForImpactID);
                                    ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                                    SQLiteDatabase dbInt = mDbHelper.getWritableDatabase();
                                    try {
                                        String whereClause = ufinDbContract.PersonalImpactInfo.COLUMN_NAME_MemberDetailsForImpactID + "=" + "'" + String.valueOf(PersonalImpactInfo.get(k).MemberDetailsForImpactID) + "'";
                                        dbInt.delete(ufinDbContract.PersonalImpactInfo.TABLE_NAME, whereClause, null);
                                    } finally {
                                        dbInt.close();
                                    }
                                }
                            }
                            //..and remove deleted records from PersonalImpactInfo ArrayList
                            for (int m = 0; m < alMarkForDelete.size(); m++) {
                                for (int k = 0; k < PersonalImpactInfo.size(); k++) {
                                    if (alMarkForDelete.get(m) == PersonalImpactInfo.get(k).MemberDetailsForImpactID) {
                                        PersonalImpactInfo.remove(k);
                                        tPersonalImpactInfo.remove(k);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
//                for (int k = 0; k < PersonalImpactInfo.size(); k++) {
//                    if (PersonalImpactInfo.get(k).MemberID != Member.get(i).MemberID)
//                        continue;
//                    PersonalImpactInfo.get(k).IsActive = Member.get(i).IsActive;
//                    tPersonalImpactInfo.get(k).IsActive = Member.get(i).IsActive;
//                }
//bmp 10-Mar-25
                SQLite_getMemberDocRcvd(Member.get(i).MemberID);
            }
            DocumentPhotos.clear();
            tDocumentPhotos.clear();
            for(int k=0; k<MemberDocRcvd.size(); k++) {
                SQLite_getDocumentPhotos(MemberDocRcvd.get(k).MemberDocuemntsRcvdID);
            }
            SQLite_getMemberFamilyDetails(Member.get(0).MemberID);
            SQLite_getFamilyImpactInfo(MemberFamilyDetails.MemberFamilyDetailsID);
            SQLite_getMemberImpactAnswer(MemberFamilyDetails.MemberFamilyDetailsID);
            boolean boolDone = false;
            for(int j=0; j<MemberImpactAnswer.size(); j++) {
                clsMemberImpactAnswer oldAnswer = MemberImpactAnswer.get(j);
                if(     ((int) oldAnswer.IPAnswerID == ImpactAnswer.HOUSE_RENTED) ||
                        ((int) oldAnswer.IPAnswerID == ImpactAnswer.HOUSE_OWNED) ) {
                    boolDone = true;
                    break;
                }
            }
            if(!boolDone) {
                clsMemberImpactAnswer newAnswer = new clsMemberImpactAnswer();
                newAnswer.Init_MemberImpactAnswer();
                newAnswer.MemberFamilyDetailsID = MemberFamilyDetails.MemberFamilyDetailsID;
                if (PersonalImpactInfo.get(0).OwnHouse == 1)
                    newAnswer.IPAnswerID = ImpactAnswer.HOUSE_OWNED;
                else
                    newAnswer.IPAnswerID = ImpactAnswer.HOUSE_RENTED;
                LastTimeInMillis += 1000;
                SQLite_saveMemberImpactAnswer(newAnswer, LastTimeInMillis, true);
                SQLite_getMemberImpactAnswer(MemberFamilyDetails.MemberFamilyDetailsID);
            }
            SQLite_getMemberAddress(Member.get(0).AddressID);

            LMFnominee.Init_LMFnominee();
            SQLite_getLMFnomineeDetails(Member.get(0).MemberID);

            Othernominee.Init_OtherNominee();
            SQLite_getOtherNomineeDetails(Member.get(0).MemberID);
            OthernomineeAddress.InitNewMemberAddress();
            SQLite_getOthernomineeAddress(Othernominee.AddressID);

            AdditionalDetails.Init_AdditionalDetails();
            SQLite_getMemberAdditionalDetails(Member.get(0).MemberID);
            //Old Members do not have record in AdditionalDetails table
            if(AdditionalDetails.MemberID != Member.get(0).MemberID)
                AdditionalDetails.MemberID = Member.get(0).MemberID;

            AdditionalDetails.LoanDuration = newGroup.arrGroupMember.get(selectedMemberPosition).LoanDuration;
            AdditionalDetails.LoanAmount = newGroup.arrGroupMember.get(selectedMemberPosition).LoanAmount;

            if(AdditionalDetails.LoanGuarantorID == 0) {
                if( (LSO_ID > 0) && (AdditionalDetails.OtherGuarantorAddressID == 0) ) {
                    clsMemberAddress newAddress = new clsMemberAddress();
                    newAddress.InitNewMemberAddress();
                    LastTimeInMillis += 1000;
                    SQLite_saveAddress(newAddress, LastTimeInMillis, true);
                    AdditionalDetails.OtherGuarantorAddressID = newAddress.AddressID;
                } else {
                    clsMemberAddress newAddress = new clsMemberAddress();
                    newAddress.InitNewMemberAddress();
                    newAddress.AddressID = AdditionalDetails.OtherGuarantorAddressID;
                    SQLite_getAddress(newAddress);
                    AdditionalDetails.GuarantorAddress = newAddress.Address;
                    AdditionalDetails.GuarantorAddressPincode = newAddress.Pincode;
                }
            }

            if(AdditionalDetails.JointLoaneeID == 0) {
                if( (LSO_ID > 0) && (AdditionalDetails.OtherJointLoaneeAddressID == 0) ) {
                    clsMemberAddress newAddress = new clsMemberAddress();
                    newAddress.InitNewMemberAddress();
                    LastTimeInMillis += 1000;
                    SQLite_saveAddress(newAddress, LastTimeInMillis, true);
                    AdditionalDetails.OtherJointLoaneeAddressID = newAddress.AddressID;
                } else {
                    clsMemberAddress newAddress = new clsMemberAddress();
                    newAddress.InitNewMemberAddress();
                    newAddress.AddressID = AdditionalDetails.OtherJointLoaneeAddressID;
                    SQLite_getAddress(newAddress);
                    AdditionalDetails.OtherJointLoaneeAddress = newAddress.Address;
                    AdditionalDetails.OtherJointLoaneePincode = newAddress.Pincode;
                }
            }

            AdditionalDetails.Copy_AdditionalDetails(tAdditionalDetails);

            currentMemberIndex = 0;
        }
    }

    public boolean PostNewGroupInfo(String strServerIP) {
        HttpURLConnection urlConnection = null;
        boolean Status = false;
        String strAPI;
        int iUploadBytes = 0;
        long lresponseTime = 0;

        for (int i = 0; i < SyncNewGroupInfo.size(); i++) {
            if (!SyncNewGroupInfo.get(i).recordReady) {
                continue;
            }

            System.out.println("PostNewGroupInfo");

            strAPI = URL_InsertNewGroupInfo;

            String strDataParamsQuery = SyncNewGroupInfo.get(i).PostParams;
            iUploadBytes = iUploadBytes + strDataParamsQuery.length();

            URL url = null;
            try {
                String strUrl = "http://" + strServerIP + ":" + strServerPort + strAPI + strDataParamsQuery;
                System.out.println(strUrl);
                url = new URL(strUrl);

                Calendar cal = Calendar.getInstance();
                long msecQueryTime = cal.getTimeInMillis();
                lresponseTime = lresponseTime + msecHttpURLConnectionTimeout;
                urlConnection = (HttpURLConnection) url.openConnection();
                urlConnection.setReadTimeout(msecHttpURLConnectionTimeout /* milliseconds */);
                urlConnection.setConnectTimeout(msecHttpURLConnectionTimeout /* milliseconds */);
                urlConnection.setRequestMethod("POST");

                urlConnection.setRequestProperty("Content-Type", "application/json");

                urlConnection.setUseCaches(false);
                urlConnection.setDoOutput(true);
                urlConnection.setDoInput(true);
//                    urlConnection.setChunkedStreamingMode(0);
                urlConnection.connect();

                String strResponse = "URL: " + strUrl + "\n" + "Response: ";
                int responseCode = urlConnection.getResponseCode();
                cal = Calendar.getInstance();
                lresponseTime = lresponseTime - msecHttpURLConnectionTimeout + (cal.getTimeInMillis() - msecQueryTime);
//bmp 06-Jan-23
//                if (responseCode == HttpURLConnection.HTTP_OK) {
                if (responseCode != HttpURLConnection.HTTP_OK) {
                    String strExceptionMessage = urlConnection.getResponseMessage();
                    System.out.println("strExceptionMessage: " + strExceptionMessage);
                    if(strExceptionMessage.contains("deadlock")) {
                        if(urlConnection != null)
                            urlConnection.disconnect();
                        break;
                    }
                    InputStream inErr = new BufferedInputStream(urlConnection.getErrorStream());
                    BufferedReader brErr = new BufferedReader(new InputStreamReader(inErr));
                    String strOutput = "";
                    int iDownloadBytes = 0;
                    while ((strOutput = brErr.readLine()) != null) {
                    }
                    brErr.close();
                    if(strOutput.contains("deadlock")) {
                        if(urlConnection != null)
                            urlConnection.disconnect();
                        break;
                    }
                } else {
//bmp 06-Jan-23
                    InputStream in = new BufferedInputStream(urlConnection.getInputStream());
                    BufferedReader br = new BufferedReader(new InputStreamReader(in));
                    String strOutput;
                    int iDownloadBytes = 0;
                    while ((strOutput = br.readLine()) != null) {
                        iDownloadBytes = iDownloadBytes + strOutput.length();
//bmp 06-Jan-23
//                        strOutput = strOutput.substring(1, (strOutput.length() - 1));
                        try {
                            if (strOutput.charAt(0) == '"') {
                                strOutput = strOutput.substring(1);
                            }
                            if (strOutput.charAt((strOutput.length() - 1)) == '"') {
                                strOutput = strOutput.substring(0, (strOutput.length() - 1));
                            }
                        } catch (Exception e) {
                            System.out.println(e.getMessage());
                        }
//bmp 06-Jan-23
                        try {
                            strResponse = strResponse + strOutput;
                            if ((strOutput.equalsIgnoreCase("1")) ||
                                    (strOutput.equalsIgnoreCase("2"))) {
                                Status = true;
                            }
                        } catch (NumberFormatException e) {
                        }
                    }
                    br.close();
                    cal = Calendar.getInstance();
                    long msecDownloadTime = cal.getTimeInMillis() - msecQueryTime;
                    downloadKBPS = (int) (iDownloadBytes / msecDownloadTime);
                }
                cal = Calendar.getInstance();
                Date date = cal.getTime();
                SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.ENGLISH);
                String strTimeStamp = sdf.format(date);// all done
                String strVersion = getString(R.string.app_name) + ": V" + getString(R.string.app_version);
                strResponse = strResponse + "\n" + strVersion + " Timestamp: " + strTimeStamp;
                if(Status) {
                    ResponseUrl.add(strResponse);
                } else {
                    DebugUrl.add(strResponse);
                }
//bmp 01-Feb-23
//                SQLite_updateNewGroupInfoACK(SyncNewGroupInfo.get(i).recordID);
//bmp 01-Feb-23
                ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
                // Gets the data repository in write mode
                SQLiteDatabase db3 = mDbHelper.getWritableDatabase();
                try {
                    String whereClause = ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName + "=" + "'" + ufinDbContract.NewGroupInfo.TABLE_NAME + "'" +
                            " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID + "=" + "'" + SyncNewGroupInfo.get(i).SyncID + "'" +
                            " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID + "=" + "'" + String.valueOf(SyncNewGroupInfo.get(i).recordID) + "'";
                    long lTemp3 = 0;
                    lTemp3 = db3.delete(ufinDbContract.RecordsToSync.TABLE_NAME, whereClause, null);
                    if (lTemp3 > 0) {
                        SyncNewGroupInfo.remove(i);
                        i = i - 1;  //avoid skipping entries by adjusting for i++
                    }
                } finally {
                    db3.close();
                }
                urlConnection.disconnect();
            } catch (Exception e) {
                e.printStackTrace();
                if(urlConnection != null)
                    urlConnection.disconnect();
                break;
            }
        }

        if(lresponseTime > 0) {
            msecResponseTime = (long) (lresponseTime / (SyncNewGroupInfo.size() + 1));
            uploadKBPS = (int) (iUploadBytes / lresponseTime);
        }

        return Status;
    }
