    public boolean GetPrePayment_PreClosureAmount(long lMemberID, int iPreClosureReasonID, int iPrePaymentORPreClosure, int iPrePaymentMonths, int iPrePaymentAmount) {
        boolean Status = false;

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        Calendar cal = Calendar.getInstance();
        Date date = cal.getTime();
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.ENGLISH);
        String strTimeStamp = sdf.format(date);// all done

        long lTemp1 = 0;
        ContentValues values1 = new ContentValues();
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PreClosureRequestDate, strTimeStamp.substring(0, 10));
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PreClosureReasonID, iPreClosureReasonID);
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PrePaymentORPreClosure, iPrePaymentORPreClosure);
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PrePaymentReqMonths, iPrePaymentMonths);
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PrePaymentReqAmount, iPrePaymentAmount);
        values1.put(ufinDbContract.MemberTransaction.COLUMN_NAME_PreClosureRequestStatus, 0);
        String whereClause = ufinDbContract.MemberTransaction.COLUMN_NAME_MemberID + "=" + "'" + String.valueOf(lMemberID) + "'";
        lTemp1 = db.update(ufinDbContract.MemberTransaction.TABLE_NAME, values1, whereClause, null);
        if (lTemp1 > 0) {
        }

        try {
            JSONObject postDataParams = new JSONObject();
            try {
                postDataParams.put("MemberID", lMemberID);
//bmp 17-Mar-26
//                postDataParams.put("CollectionDate", strTimeStamp.substring(0, 10));
                postDataParams.put("CollectionDate", strTimeStamp);
//bmp 17-Mar-26
////bmp 24-Dec-25
////                postDataParams.put("PreClosureReason", strPreClosureReason);
//                if(strPreClosureReason.isEmpty())
//                    postDataParams.put("PreClosureReason", "NA");
//                else
//                    postDataParams.put("PreClosureReason", strPreClosureReason);
////bmp 24-Dec-25
                postDataParams.put("PreClosureReasonID", iPreClosureReasonID);
                postDataParams.put("PrePaymentMonth", iPrePaymentMonths);
                postDataParams.put("PrePaymentAmount", iPrePaymentAmount);
                postDataParams.put("Org_ID", OrgID);
            } catch (JSONException e) {
                e.printStackTrace();
            }
            String strDataParamsQuery = "";
            try {
                StringBuilder sb = new StringBuilder();
                Iterator<String> keys = postDataParams.keys();
                sb.append("?"); //start of query args
                while (keys.hasNext()) {
                    String key = keys.next();
                    sb.append(key);
                    sb.append("=");
                    sb.append(postDataParams.get(key));
                    sb.append("&"); //To allow for another argument.
                }
                strDataParamsQuery = sb.toString();
                strDataParamsQuery = strDataParamsQuery.substring(0, (strDataParamsQuery.length() - 1));
                strDataParamsQuery = strDataParamsQuery.replaceAll(" ", "%20");
            } catch (JSONException e) {
                e.printStackTrace();
            }

            long lTemp2 = 0;
            ContentValues values2 = new ContentValues();

            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID, strTimeStamp);
//            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName, "PreClosureRequest");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName, "PrePayment_PreClosureRequest");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID, lMemberID);
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsNewRecord, "True");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsReady, "True");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_PostDataParams, strDataParamsQuery);

            lTemp2 = db.insert(ufinDbContract.RecordsToSync.TABLE_NAME, null, values2);
            if (lTemp2 > 0) {
                MainActivity.clsRecordsToSync newRec = new MainActivity.clsRecordsToSync();
                newRec.SyncID = strTimeStamp;
                newRec.recordID = lMemberID;
                newRec.recordInserted = true;
                newRec.recordReady = true;
                newRec.PostParams = strDataParamsQuery;
                SyncPrePayment_PreClosureRequest.add(newRec);
                File packetFile = new File(baseDir + "/config/" + strPacketFile);
                try {
                    BufferedWriter bwr = new BufferedWriter(new FileWriter(packetFile, true));
                    bwr.newLine();
                    bwr.newLine();
                    bwr.write(strDataParamsQuery);
                    bwr.flush();
                    bwr.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }

                System.out.println("RecordsToSync Updated.");
                Status = true;
            }
        } finally {
            db.close();
        }

        return Status;
    }
