                    String whereClause = ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName + "=" + "'" + "CollectionSMS" + "'" +
                            " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID + "=" + "'" + SyncCollectionSMS.get(i).SyncID + "'" +
                            " AND " + ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID + "=" + "'" + String.valueOf(SyncCollectionSMS.get(i).recordID) + "'";
                    long lTemp3 = 0;
                    lTemp3 = db3.delete(ufinDbContract.RecordsToSync.TABLE_NAME, whereClause, null);
