    public class GFPagerAdapter extends FragmentStatePagerAdapter {
        int mNumOfTabs;

        public GFPagerAdapter(FragmentManager fm, int NumOfTabs) {
            super(fm);
            this.mNumOfTabs = NumOfTabs;
        }

        @Override
        public Fragment getItem(int position) {

            switch (position) {
                case GF_FRAGMENT_SEQUENCE_NUMBER_GROUPFORM:
                    GroupformFragment tab0 = new GroupformFragment();
                    return tab0;
                case GF_FRAGMENT_SEQUENCE_NUMBER_SCHEDULE:
                    ScheduleFragment tab1 = new ScheduleFragment();
                    return tab1;
                case GF_FRAGMENT_SEQUENCE_NUMBER_ROLL_OVER:
                    GroupformFragment tab2 = new GroupformFragment();
                    return tab2;
                default:
                    return null;
            }
        }

        @Override
        public int getCount() {
            return mNumOfTabs;
        }
    }
    public class CollectionPagerAdapter extends FragmentStatePagerAdapter {
        int mNumOfTabs;

        public CollectionPagerAdapter(FragmentManager fm, int NumOfTabs) {
            super(fm);
            this.mNumOfTabs = NumOfTabs;
        }

        @Override
        public Fragment getItem(int position) {

            switch (position) {
                case COLLECTION_FRAGMENT_SEQUENCE_NUMBER_SCHEDULE:
                    ScheduleFragment tab1 = new ScheduleFragment();
                    return tab1;
                case COLLECTION_FRAGMENT_SEQUENCE_NUMBER_COLLECTION:
                    CollectionFragment tab0 = new CollectionFragment();
                    return tab0;
                case COLLECTION_FRAGMENT_SEQUENCE_NUMBER_ONLINE_COLLECTION:
                    OnlineCollectionFragment tab2 = new OnlineCollectionFragment();
                    return tab2;
                case COLLECTION_FRAGMENT_SEQUENCE_NUMBER_ROLL_OVER:
                    CollectionFragment tab3 = new CollectionFragment();
                    return tab3;
                default:
                    return null;
            }
        }

        @Override
        public int getCount() {
            return mNumOfTabs;
        }
    }

    boolean LoanApplicationForBusiness(long lReasonID) {
        boolean LoanForBusiness = false;

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();

        // Define a projection that specifies which columns from the database
        // you will actually use after this query.
        String[] projection1 = {
                ufinDbContract.ReasonMaster.COLUMN_NAME_Reason,
        };

        String selection1 = ufinDbContract.ReasonMaster.COLUMN_NAME_ReasonID + "=" + "'" + String.valueOf(lReasonID) + "'";

        // How you want the results sorted in the resulting Cursor
//        String sortOrder1 = ufinDbContract.ReasonMaster.COLUMN_NAME_SequenceID + " ASC";

        Cursor c1 = db.query(
                ufinDbContract.ReasonMaster.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                selection1,                                // The columns for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                null	                                 // The sort order
        );

        try {
            if (c1 != null && c1.moveToFirst()) {
                if (c1.getCount() > 0) {
                    try {
                        String strReason = c1.getString(c1.getColumnIndexOrThrow(ufinDbContract.ReasonMaster.COLUMN_NAME_Reason));
                        if(strReason.contains("Business")) {
                            LoanForBusiness = true;
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } finally {
            if(c1 != null) { c1.close(); }
            db.close();
        }

        return LoanForBusiness;
    }
