    boolean isDocumentPhotoAvailable(long memberID, long docID) {
        for(int i=0; i<MemberDocRcvd.size(); i++) {
            if ((MemberDocRcvd.get(i).IsActive == 1) &&
                    (MemberDocRcvd.get(i).MemberID == memberID) &&
                    (MemberDocRcvd.get(i).MemberDocumentsID == docID)) {
                for (int k = 0; k < DocumentPhotos.size(); k++) {
                    if ((MemberDocRcvd.get(i).MemberDocuemntsRcvdID ==
                            DocumentPhotos.get(k).MemberDocuemntsRcvdID) &&
                            (DocumentPhotos.get(k).IsActive == 1)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

