    public void SortRecordsToSync(ArrayList<clsRecordsToSync> arrList) {
        ArrayList<Long> arrListTimeStamp = new ArrayList<Long>();
        arrListTimeStamp.clear();
        for(int i=0; i<arrList.size(); i++) {
            clsRecordsToSync newRecord = arrList.get(i);
            String strTimeStamp = newRecord.SyncID;
            long lTimeStamp = 0L;
            try {
                Calendar recordTimeStamp = Calendar.getInstance();
                recordTimeStamp.set(Calendar.YEAR, Integer.parseInt(strTimeStamp.substring(0, 4)));
                recordTimeStamp.set(Calendar.MONTH, (Integer.parseInt(strTimeStamp.substring(5, 7)) - 1));
                recordTimeStamp.set(Calendar.DATE, Integer.parseInt(strTimeStamp.substring(8, 10)));
                recordTimeStamp.set(Calendar.HOUR, Integer.parseInt(strTimeStamp.substring(11, 13)));
                recordTimeStamp.set(Calendar.MINUTE, Integer.parseInt(strTimeStamp.substring(14, 16)));
                recordTimeStamp.set(Calendar.SECOND, Integer.parseInt(strTimeStamp.substring(17, 19)));
//bmp 16-May-23
                recordTimeStamp.set(Calendar.MILLISECOND, Integer.parseInt(strTimeStamp.substring(20, 23)));
//bmp 16-May-23
                lTimeStamp = recordTimeStamp.getTimeInMillis();
            }catch (Exception e){
                System.out.println(e.getMessage());
            }
            arrListTimeStamp.add(lTimeStamp);
        }

        int sortLength = arrList.size();   //10
        for(int k=0; k<(arrList.size() - 1); k++) {    //0 to 9
            int iLatestTimeStampIndex = 0;
            for (int i = 1; i < sortLength; i++) {  //1 to 9, 1 to 8, 1 to 7, ... 1 to 1
                if (arrListTimeStamp.get(i) >= arrListTimeStamp.get(iLatestTimeStampIndex)) {
                    iLatestTimeStampIndex = i;
                }
            }
            if (iLatestTimeStampIndex != (sortLength - 1)) {
                System.out.println("Out of Order packet found");
                clsRecordsToSync latestRecord = arrList.get(iLatestTimeStampIndex);
                clsRecordsToSync tempRecord = arrList.get(sortLength - 1);
                arrList.set((sortLength - 1), latestRecord);
                arrList.set(iLatestTimeStampIndex, tempRecord);
                Long lLatest = arrListTimeStamp.get(iLatestTimeStampIndex);
                Long lTemp = arrListTimeStamp.get((sortLength - 1));
                arrListTimeStamp.set((sortLength - 1), lLatest);
                arrListTimeStamp.set(iLatestTimeStampIndex, lTemp);
            }
            sortLength--;
        }
    }

