    public int searchScheduleActivity(String strType, String strDetails) {
        int iIndex = -1;

        if(!strType.isEmpty() && !strDetails.isEmpty()) {
            for (int i=0; i<ActivitySchedule.size(); i++) {
                if(     (strType.equalsIgnoreCase(ActivitySchedule.get(i).ActivityType)) &&
                        (strDetails.equalsIgnoreCase(ActivitySchedule.get(i).ActivityDetails)) ) {
                    iIndex = i;
                    break;
                }
            }
        }
        return iIndex;
    }
    public boolean searchScheduleTime(String strType, String strDetails, long lStart, long lEnd) {
        boolean bFlagInvalid = false;
        if(strType.equalsIgnoreCase("PIF")) {
            for (int i = 0; i < ActivitySchedule.size(); i++) {
//bmp 20-Aug-25
//                if (ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("GRT") ||
//                        ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("Orientation")) {
                if (ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("GRT")) {
//bmp 20-Aug-25
                    //BM activity will not clash with LSO new activity
                    continue;
                }
                if (ActivitySchedule.get(i).EndTime == 0) {
                    //Flexible activity will not clash with new activity
                    continue;
                }
                if (ActivitySchedule.get(i).EndTime <= lStart) {
                    //Activity ends before new activity
                    continue;
                }
                if (ActivitySchedule.get(i).StartTime >= lEnd) {
                    //Activity Starts after new activity
                    continue;
                }
                //Activity overlaps with new activity
                if ((!ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType)) ||
//bmp 03-Apr-24
//                        (!ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase(strDetails))) {
                        (!ActivitySchedule.get(i).ActivityDetails.contains(strDetails))) {
//bmp 03-Apr-24
                    //Activity is Not same as new activity
                    bFlagInvalid = true;
                    break;
                }
            }

            return bFlagInvalid;
        } else if(strType.equalsIgnoreCase("Recovery")) {
            for (int i=0; i<ActivitySchedule.size(); i++) {
//bmp 20-Aug-25
//                if(     ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("GRT") ||
//                        ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("Orientation")    ) {
                if(ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("GRT")) {
//bmp 20-Aug-25
                    //BM activity will not clash with LSO new activity
                    continue;
                }
                if(ActivitySchedule.get(i).EndTime == 0) {
                    //Flexible activity will not clash with new activity
                    continue;
                }
                if(ActivitySchedule.get(i).EndTime <= lStart) {
                    //Activity ends before new activity
                    continue;
                }
                if(ActivitySchedule.get(i).StartTime >= lEnd) {
                    //Activity Starts after new activity
                    continue;
                }
                //Activity overlaps with new activity
                if(     (!ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType)) ||
                        (!ActivitySchedule.get(i).ActivityDetails.contains(strDetails)) ) {
                    //Activity is Not same as new activity
                    bFlagInvalid = true;
                    break;
                }
            }

            return bFlagInvalid;
        } else if(strType.equalsIgnoreCase("GRT")) {
            bFlagInvalid = true;
            for (int i=0; i<ActivitySchedule.size(); i++) {
                if(!ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("GRT")) {
                    continue;
                }
                if(!ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase("Empty Time Slot")) {
                    if(!ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase(strDetails)) {
                        //Other Group GRT slot
                        continue;
                    } else {
                        //Same Group GRT slot
                        if(     (ActivitySchedule.get(i).StartTime == lStart) &&
                                (ActivitySchedule.get(i).EndTime == lEnd)   ) {
                            bFlagInvalid = false;
                            break;
                        }
                    }
                } else {
                    //Vacant GRT slot
                    bFlagInvalid = false;
                    break;
                }
            }

            return bFlagInvalid;
//bmp 20-Aug-25
//        } else if(strType.equalsIgnoreCase("Orientation")) {
//            bFlagInvalid = true;
//            for (int i=0; i<ActivitySchedule.size(); i++) {
//                if(!ActivitySchedule.get(i).ActivityType.equalsIgnoreCase("Orientation")) {
//                    continue;
//                }
//                if(!ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase("Empty Time Slot")) {
//                    if(!ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase(strDetails)) {
//                        //Other Group Orientation slot
//                        continue;
//                    } else {
//                        //Same Group Orientation slot
//                        if(     (ActivitySchedule.get(i).StartTime == lStart) &&
//                                (ActivitySchedule.get(i).EndTime == lEnd)   ) {
//                            bFlagInvalid = false;
//                            break;
//                        }
//                    }
//                } else {
//                    //Vacant Orientation slot
//                    bFlagInvalid = false;
//                    break;
//                }
//            }
//
//            return bFlagInvalid;
//bmp 20-Aug-25
        }

        return bFlagInvalid;
    }
    public boolean insertSchedule(String strType, String strDetails, long lStart, long lEnd) {
        boolean bFlag = false;

        clsSchedule newSchedule = new clsSchedule();
        newSchedule.StartTime = lStart;
        newSchedule.EndTime = lEnd;
        newSchedule.ActivityType = strType;
        newSchedule.ActivityDetails = strDetails;

        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        ContentValues values2 = new ContentValues();
        values2.put(ufinDbContract.ActivitySchedule.COLUMN_NAME_StartTime, newSchedule.StartTime);
        values2.put(ufinDbContract.ActivitySchedule.COLUMN_NAME_EndTime, newSchedule.EndTime);
        values2.put(ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityType, newSchedule.ActivityType);
        values2.put(ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityDetails, newSchedule.ActivityDetails);

        try {
            if(strType.equalsIgnoreCase("Recovery")) {
                String whereClause2 = ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityType + "=" + "'" + newSchedule.ActivityType + "'"
                        + " and " + ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityDetails + "=" + "'" + newSchedule.ActivityDetails + "'";
                long lTemp1 = db.update(ufinDbContract.ActivitySchedule.TABLE_NAME, values2, whereClause2, null);
                if (lTemp1 > 0) {
                    for (int i = 0; i < ActivitySchedule.size(); i++) {
                        if (ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType) &&
                                ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase(strDetails)) {
                            ActivitySchedule.get(i).StartTime = lStart;
                            ActivitySchedule.get(i).EndTime = lEnd;
                            break;
                        }
                    }
                    bFlag = true;
                } else {
                    lTemp1 = db.insert(ufinDbContract.ActivitySchedule.TABLE_NAME, null, values2);
                    ActivitySchedule.add(newSchedule);
                    bFlag = true;
                }
            } else if(strType.equalsIgnoreCase("PIF")) {
                String strCompare = strDetails;
                if(strDetails.contains(":")) {
                    String[] strSplit = strDetails.split(":");
                    strCompare = strSplit[0];
                }
                String strCompareGroupID = strCompare + "%";
                String whereClause2 = ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityType + "=" + "'" + newSchedule.ActivityType + "'"
                        + " and " + ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityDetails + " like " + "'" + strCompareGroupID + "'";
                long lTemp1 = db.update(ufinDbContract.ActivitySchedule.TABLE_NAME, values2, whereClause2, null);
                if (lTemp1 > 0) {
                    for (int i = 0; i < ActivitySchedule.size(); i++) {
                        if (ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType) &&
                                ActivitySchedule.get(i).ActivityDetails.contains(strCompare)) {
                            ActivitySchedule.get(i).ActivityDetails = strDetails;
                            ActivitySchedule.get(i).StartTime = lStart;
                            ActivitySchedule.get(i).EndTime = lEnd;
                            break;
                        }
                    }
                    bFlag = true;
                } else {
                    lTemp1 = db.insert(ufinDbContract.ActivitySchedule.TABLE_NAME, null, values2);
                    ActivitySchedule.add(newSchedule);
                    bFlag = true;
                }
            } else {
                String whereClause2 = ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityType + "=" + "'" + newSchedule.ActivityType + "'"
                        + " and " + ufinDbContract.ActivitySchedule.COLUMN_NAME_StartTime + "=" + "'" + String.valueOf(newSchedule.StartTime) + "'";
                long lTemp1 = db.delete(ufinDbContract.ActivitySchedule.TABLE_NAME, whereClause2, null);
                for(int i=0; i<ActivitySchedule.size(); i++) {
                    if (    ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType) &&
                            (ActivitySchedule.get(i).StartTime == lStart)   ) {
                        ActivitySchedule.remove(i);
                        break;
                    }
                }
//bmp 28-Jul-25
                //Remove previous "GRT" or "Orientation" schedule entry for same GroupID if any.
                String whereClause3 = ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityType + "=" + "'" + newSchedule.ActivityType + "'"
                        + " and " + ufinDbContract.ActivitySchedule.COLUMN_NAME_ActivityDetails + "=" + "'" + newSchedule.ActivityDetails + "'";
                long lTemp2 = db.delete(ufinDbContract.ActivitySchedule.TABLE_NAME, whereClause3, null);
                for(int i=0; i<ActivitySchedule.size(); i++) {
                    if (    ActivitySchedule.get(i).ActivityType.equalsIgnoreCase(strType) &&
                            (ActivitySchedule.get(i).ActivityDetails.equalsIgnoreCase(newSchedule.ActivityDetails)) ) {
                        ActivitySchedule.remove(i);
//                        break;
                        i = i - 1;
                    }
                }
//bmp 28-Jul-25
                lTemp1 = db.insert(ufinDbContract.ActivitySchedule.TABLE_NAME, null, values2);
                ActivitySchedule.add(newSchedule);
                bFlag = true;
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }

        db.close();

        return bFlag;
    }
    public boolean GetDeviceLocation() {
        boolean bFlag = false;
        if (ActivityCompat.checkSelfPermission(this, ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED && ActivityCompat.checkSelfPermission(this, ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
            // TODO: Consider calling
            //    ActivityCompat#requestPermissions
            // here to request the missing permissions, and then overriding
            //   public void onRequestPermissionsResult(int requestCode, String[] permissions,
            //                                          int[] grantResults)
            // to handle the case where the user grants the permission. See the documentation
            // for ActivityCompat#requestPermissions for more details.
            return bFlag;
        }
        try {
            LocationManager locManager = (LocationManager) getSystemService(Context.LOCATION_SERVICE);
            List strList = locManager.getAllProviders();
            System.out.println(strList);

            Location getLastLocation = locManager.getLastKnownLocation(LocationManager.GPS_PROVIDER);
            if(getLastLocation == null)
                getLastLocation = locManager.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);
            if(getLastLocation == null)
                getLastLocation = locManager.getLastKnownLocation(LocationManager.PASSIVE_PROVIDER);
            if(getLastLocation != null) {
                double currentLongitude = getLastLocation.getLongitude();
                double currentLatitude = getLastLocation.getLatitude();
                strDeviceLongitude = String.valueOf(currentLongitude);
                strDeviceLatitude = String.valueOf(currentLatitude);
                System.out.println("currentLongitude: " + strDeviceLongitude);
                System.out.println("currentLatitude: " + strDeviceLatitude);
                bFlag = true;
                //acos(sin(lat1)*sin(lat2)+cos(lat1)*cos(lat2)*cos(lon2-lon1))*6371
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }

        return bFlag;
    }
    public boolean UpdateTabLocation(String strActivity) {
        boolean Status = false;

        if(!GetDeviceLocation()) {
            return Status;
        }
//bmp 13-Aug-25
        if(GetDeviceDigiPin()) {
//bmp 18-Sep-25
            if(strDeviceDigiPin.isEmpty())
                strDeviceDigiPin = "NA";
//bmp 18-Sep-25
            System.out.println("strDeviceDigiPin = " + strDeviceDigiPin);
        }
//bmp 13-Aug-25
        ufinDbHelper mDbHelper = new ufinDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        Calendar cal = Calendar.getInstance();
        Date date = cal.getTime();
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.ENGLISH);
        String strTimeStamp = sdf.format(date);// all done

        try {
            JSONObject postDataParams = new JSONObject();
            try {
                postDataParams.put("Remarks", strActivity);
                postDataParams.put("LocationDateTime", strTimeStamp);
                postDataParams.put("Latitude", strDeviceLatitude);
                postDataParams.put("Longitude", strDeviceLongitude);
//bmp 13-Aug-25
                postDataParams.put("DigiPin", strDeviceDigiPin);
//bmp 13-Aug-25
                postDataParams.put("ORGStructureID", LSO_ID);
                postDataParams.put("Org_ID", OrgID);
            } catch (JSONException e) {
                e.printStackTrace();
            }
            String strDataParamsQuery = "";
            try {
                StringBuilder sb = new StringBuilder();
                Iterator<String> keys = postDataParams.keys();
                sb.append("?"); //start of query args
                while (keys.hasNext()) {
                    String key = keys.next();
                    sb.append(key);
                    sb.append("=");
                    sb.append(postDataParams.get(key));
                    sb.append("&"); //To allow for another argument.
                }
                strDataParamsQuery = sb.toString();
                strDataParamsQuery = strDataParamsQuery.substring(0, (strDataParamsQuery.length() - 1));
                strDataParamsQuery = strDataParamsQuery.replaceAll(" ", "%20");
            } catch (JSONException e) {
                e.printStackTrace();
            }

            long lTemp1 = 0;
            ContentValues values2 = new ContentValues();

            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_SyncID, strTimeStamp);
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_DbTableName, "TabLocation");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_updatedRecordID, LSO_ID);
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsNewRecord, "True");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_IsReady, "True");
            values2.put(ufinDbContract.RecordsToSync.COLUMN_NAME_PostDataParams, strDataParamsQuery);

            lTemp1 = db.insert(ufinDbContract.RecordsToSync.TABLE_NAME, null, values2);
            if (lTemp1 > 0) {
                MainActivity.clsRecordsToSync newRec = new MainActivity.clsRecordsToSync();
                newRec.SyncID = strTimeStamp;
                newRec.recordID = LSO_ID;
                newRec.recordInserted = true;
                newRec.recordReady = true;
                newRec.PostParams = strDataParamsQuery;
                SyncTabLocation.add(newRec);
                File packetFile = new File(baseDir + "/config/" + strPacketFile);
                try {
                    BufferedWriter bwr = new BufferedWriter(new FileWriter(packetFile, true));
                    bwr.newLine();
                    bwr.newLine();
                    bwr.write(strDataParamsQuery);
                    bwr.flush();
                    bwr.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }

                System.out.println("RecordsToSync Updated.");
                Status = true;
            }
        } finally {
            db.close();
        }

        return Status;
    }
