    public long AddDocumentPhotos(long DocRcvdID, long groupID, boolean syncRecord) {
        clsDocumentPhoto newDocPhoto = new clsDocumentPhoto();
        newDocPhoto.Init_DocumentPhoto();
        newDocPhoto.MemberDocuemntsRcvdID = DocRcvdID;
        newDocPhoto.GroupID = groupID;
//bmp 08-Apr-26
        if(DocRcvdID == 0) {
            newDocPhoto.MemberDocumentsID = clsDocumentIDs.MEMBER_DOC_ID_NEXTLOAN_NOT_REQ_UNDERTAKING;
        }
//bmp 08-Apr-26

        DocumentPhotos.add(newDocPhoto);
        int newIndex = DocumentPhotos.size() - 1;

        Calendar cal = Calendar.getInstance();
        while(LastTimeInMillis > cal.getTimeInMillis()) {
            cal = Calendar.getInstance();
        }
        LastTimeInMillis = cal.getTimeInMillis();

        LastTimeInMillis += 1000;
        SQLite_saveDocumentPhoto(newIndex, LastTimeInMillis, syncRecord);
        newDocPhoto.DocumentPhotoID = DocumentPhotos.get(newIndex).DocumentPhotoID;

        clsDocumentPhoto tnewDocPhoto = new clsDocumentPhoto();
        newDocPhoto.Copy_DocumentPhoto(tnewDocPhoto);
        tDocumentPhotos.add(tnewDocPhoto);

        return newDocPhoto.DocumentPhotoID;
    }
