    public void CreateAlertDialog(boolean enablePositiveButton, boolean enableNegativeButton) {
        dlgAlert = new AlertDialog.Builder(MainActivity.this);
//        dlgAlert.setTitle(getString(R.string.app_name));
        TextView tvTitle = new TextView(MainActivity.this);
        tvTitle.setText(getString(R.string.app_name));
        tvTitle.setTextSize(30);
        tvTitle.setTextColor(getResources().getColor(R.color.colorAccent));
        dlgAlert.setCustomTitle(tvTitle);
        dlgAlert.setIcon(R.drawable.ic_launcher_foreground);
        if(enableNegativeButton) {
            dlgAlert.setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
                public void onClick(DialogInterface dialog, int id) {
                    // User clicked Cancel button
                    dialog.dismiss();

                    switch (dlgState) {
                        case ufin_DIALOG_STATE_NONE:
                            break;
                        case ufin_DIALOG_STATE_SERVER_DB_SYNC_UP:
                            iServerSyncState = ServerSyncState_Periodical_01;

                            Message msg;
                            Bundle messageData;
                            msg = Message.obtain(SyncByIndexHandler);
                            messageData = new Bundle();
                            msg.what = 1;
                            messageData.putString("Status", "Initial Sync-up with Server Database Completed.");
                            msg.setData(messageData);
                            SyncByIndexHandler.sendMessage(msg);
                            break;
                        case ufin_DIALOG_STATE_START_OF_DAY_SYNCUP:
                        case ufin_DIALOG_STATE_LOCATION_NOT_FOUND:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                    }
                }
            });
            dlgAlert.setCancelable(true);
        }
        if(enablePositiveButton) {
            dlgAlert.setPositiveButton("OK", new DialogInterface.OnClickListener() {
                public void onClick(DialogInterface dialog, int id) {
                    // User clicked OK button
                    dialog.dismiss();

                    switch (dlgState) {
                        case ufin_DIALOG_STATE_NONE:
                            break;
                        case ufin_DIALOG_STATE_REGISTER:
                            Button bt = (Button) findViewById(R.id.buttonRegister);
                            if(bt != null)
                                bt.setEnabled(true);
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                        case ufin_DIALOG_STATE_REGISTER_SUCCESS:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            android.os.Process.killProcess(android.os.Process.myPid());
                            break;
                        case ufin_DIALOG_STATE_LOGIN:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                        case ufin_DIALOG_STATE_CLOSE:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            InitDesktop();
                            break;
//                        case ufin_DIALOG_STATE_CLOSE_GROUP:
//                            dlgState = ufin_DIALOG_STATE_NONE;
//                            InitDesktop();
//                            break;
                        case ufin_DIALOG_STATE_VALIDATE_PIF_SCREEN:
                            CustomViewPager viewPager = (CustomViewPager) findViewById(R.id.viewpagerPIF);
                            iCurrentScreen++;
                            if (iCurrentScreen == PIF_FRAGMENT_SEQUENCE_NUMBER_ROLL_OVER)
                                iCurrentScreen = PIF_FRAGMENT_SEQUENCE_NUMBER_MEMBER;
                            viewPager.setCurrentItem(iCurrentScreen);
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                        case ufin_DIALOG_STATE_SERVER_DB_SYNC_UP:
                            UpdateFromCSVDatabase();
                            iServerSyncState = ServerSyncState_Periodical_01;
                            break;
                        case ufin_DIALOG_STATE_SERVER_DB_SYNC_UP_STATUS:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                        case ufin_DIALOG_STATE_INVALID_DEVICE_DATE:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            android.os.Process.killProcess(android.os.Process.myPid());
                            break;
                        case ufin_DIALOG_STATE_START_OF_DAY_SYNCUP:
                        case ufin_DIALOG_STATE_MEMBER_PIF_NOT_AVAILABLE:
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                        case ufin_DIALOG_STATE_LOCATION_NOT_FOUND:
//bmp 14-Jan-26
                            ClearOutdatedPreClosureRequests();
//bmp 14-Jan-26
                            InitDesktop();
                            dlgState = ufin_DIALOG_STATE_NONE;
                            break;
                    }
                }
            });
        }
//        dlgAlert.setCancelable(true);
    }
    public void CreateDefaultConfig() {
        String myDir = baseDir;
        File folder = new File(myDir);
        if (!folder.exists())
            folder.mkdir();

        File folder1 = new File(myDir + "/config");
        if (!folder1.exists())
            folder1.mkdir();
        File folder2 = new File(myDir + "/data");
        if (!folder2.exists())
            folder2.mkdir();
        File folder3 = new File(myDir + "/upload");
        if (!folder3.exists())
            folder3.mkdir();
        File folder4 = new File(myDir + "/download");
        if (!folder4.exists())
            folder4.mkdir();

        Intent mediaScannerIntent = new Intent(Intent.ACTION_MEDIA_SCANNER_SCAN_FILE);
        Uri fileContentUri = FileProvider.getUriForFile(getApplicationContext(), getApplicationContext().getPackageName() + ".provider", new File(myDir));
        mediaScannerIntent.setData(fileContentUri);
        this.sendBroadcast(mediaScannerIntent);
    }

    //PY
    private void startNetworkMonitoring() {
        Intent monitorIntent = new Intent(this, NetworkMonitorService.class);
        monitorIntent.putExtra(NetworkMonitorService.EXTRA_WORKER_ID, String.valueOf(LSO_ID));
        monitorIntent.putExtra(NetworkMonitorService.EXTRA_LOGIN_ID, LoginID);
        monitorIntent.putExtra(NetworkMonitorService.EXTRA_LSO_ID, LSO_ID);
        monitorIntent.putExtra(NetworkMonitorService.EXTRA_ORG_ID, OrgID);
        ContextCompat.startForegroundService(this, monitorIntent);
    }
